const module_26669 = (e,a,n)=>{"use strict";n.r(a),n.d(a,{default:()=>A});var i=n(4948),t=n(46173),r=n(99808),o=n(27214),s=n(14029),l=n(75435),d=n(34988),c=n(29979),u=n(83593);let m=JSON.parse('[{"key":"tangtang","name":"Tangtang","codename":"Tangtang","camp":"Tập Đo\xe0n Endfield","race":"Feline","rarity":6,"intro":"“Thủ Lĩnh Tối Cao đ\xe2y! Ngươi, ngươi v\xe0 cả ngươi, tất cả đều nghe theo lệnh của ta” \\nTangtang, Thủ Lĩnh Tối Cao của Trại Thanh Ba. T\xednh c\xe1ch thẳng thắn, coi trọng l\xf2ng trung th\xe0nh v\xe0 h\xe0nh động theo bản năng tự do, ph\xf3ng kho\xe1ng, kh\xf4ng chịu r\xe0ng buộc theo khu\xf4n ph\xe9p. Tangtang y\xeau sự tự do, th\xedch đ\xf9a nghịch giữa l\xe0n nước, nhưng căm gh\xe9t sự phản bội. Một khi đ\xe3 thừa nhận ai l\xe0 bạn, c\xf4 b\xe9 sẽ dốc hết sức m\xecnh để gi\xfap đỡ. \\nKhi mới lọt l\xf2ng, Tangtang được một người kh\xf4ng r\xf5 danh t\xednh đặt v\xe0o một chiếc giỏ tre, thả tr\xf4i theo d\xf2ng s\xf4ng, để rồi dạt đến Trại Thanh Ba. Tại đ\xe2y, c\xf4 b\xe9 được D\xe2n Trại cưu mang, nu\xf4i nấng v\xe0 trở th\xe0nh một phần của Trại. Trong mắt nhiều người, Tangtang vẫn chỉ l\xe0 đứa trẻ cần được chở che, nhưng trong s\xe2u thẳm t\xe2m hồn, c\xf4 từ l\xe2u đ\xe3 hạ quyết t\xe2m g\xe1nh v\xe1c tương lai của Trại Thanh Ba. \\nTuy trải qua kh\xf4ng \xedt biến cố nhưng ngọn lửa nhiệt huyết trong c\xf4 b\xe9 chưa từng lụi t\xe0n. Để giải đ\xe1p cho những ho\xe0i nghi trong l\xf2ng v\xe0 đưa Trại Thanh Ba ph\xe1t triển hơn nữa, Tangtang đ\xe3 gia nhập Tập Đo\xe0n Endfield. \\n“Đừng để c\xf4 b\xe9 thấy Mi Fu, nếu kh\xf4ng th\xec rối tung hết l\xean đấy.” — theo lời c\xe1n vi\xean ở Văn Ph\xf2ng Trưởng Vận Chuyển. \\n“Gọi ta đến chỉ để khen th\xf4i \xe0? Thế th\xec khen nhiều v\xe0o. Ta th\xedch nghe lời n\xf3i thật lắm!”","prof":"caster","elem":"ice","cv":{"en-us":"Jing Chen"}},{"key":"rossi","name":"Rossi","codename":"Rossi","camp":"Tập Đo\xe0n Endfield","race":"Lupo","rarity":6,"intro":"“Với người ưu t\xfa như em th\xec đơn giản!” \\nRossina Wulfperl Luppino, em g\xe1i của Wulfgard, Vi\xean Ngọc Tộc S\xf3i. Trong cuộc xung đột giữa Tộc S\xf3i v\xe0 Bonekrusher, rất nhiều s\xf3i trưởng l\xe3o trong tộc đ\xe3 phải trả gi\xe1 bằng m\xe1u để cứu c\xf4 b\xe9. Ng\xe0y ấy, m\xe1u đ\xe3 nhuộm đỏ tấm khăn quấn quanh c\xf4 b\xe9… \\nWulfgard hoạt động t\xe1ch biệt với tộc suốt nhiều năm, nhưng khi Tộc S\xf3i cần một người đứng đầu, Rossi đ\xe3 lựa chọn g\xe1nh lấy tr\xe1ch nhiệm ấy. C\xf4 lu\xf4n tin rằng người anh trai sớm vang danh khi c\xf2n rất trẻ mới xứng đ\xe1ng dẫn dắt to\xe0n Tộc S\xf3i. V\xec thế, Rossi kh\xf4ng ngừng nhắc nhở v\xe0 th\xfac giục anh đảm nhận vị tr\xed đ\xf3. Dẫu c\xe1c bậc trưởng l\xe3o trong tộc mong c\xf4 c\xf3 thể d\xe0nh nhiều thời gian để sống đ\xfang với đam m\xea như những c\xf4 g\xe1i c\xf9ng tuổi, Rossi vẫn kh\xf4ng thể gạt bỏ g\xe1nh nặng mang t\xean “tr\xe1ch nhiệm” trong l\xf2ng. V\xec gia đ\xecnh, v\xec tộc nh\xe2n, c\xf4 kh\xf4ng ngừng r\xe8n giũa bản th\xe2n để trở n\xean vững v\xe0ng v\xe0 mạnh mẽ hơn. \\nRossi lu\xf4n mơ về những c\xe2u chuyện anh h\xf9ng, c\xf3 những khi cũng mơ mộng rằng sẽ c\xf3 một ng\xe0y c\xf4 được dấn th\xe2n v\xe0o những cuộc phi\xeau lưu c\xf9ng c\xe1c anh h\xf9ng trứ danh. Đ\xf3 ch\xednh l\xe0 khoảnh khắc “cho ri\xeang m\xecnh” hiếm hoi m\xe0 c\xf4 \xe2m thầm g\xecn giữ. \\n“Ch\xfang cắn r\xe1t đấy, nhưng Tộc S\xf3i kh\xf4ng sợ sẹo đ\xe2u!”","prof":"guard","elem":"physic","cv":{"en-us":"Giada Sabellico"}},{"key":"endministrator2","name":"Endministrator","codename":"Endministrator","camp":"Tập Đo\xe0n Endfield","race":"Kh\xf4ng Tiết Lộ","rarity":6,"intro":"Endministrator của Tập Đo\xe0n Endfield.\\nTrong lịch sử ghi ch\xe9p của Talos-II, Endministrator được xem l\xe0 vệ binh then chốt, người đ\xe3 che chở cho nền văn minh tr\xean h\xe0nh tinh n\xe0y v\xe0 cứu nh\xe2n loại tho\xe1t khỏi v\xf4 số thảm họa diệt vong. Những chiến c\xf4ng hiển h\xe1ch của Endmin đ\xe3 tạo n\xean v\xf4 số c\xe2u chuyện, truyền thuyết v\xe0 cả những lời đồn đại. \\nThế nhưng, th\xe2n phận thật sự của Endmin vẫn l\xe0 ẩn số, chỉ một số \xedt người từng tận mắt chứng kiến huyền thoại sống n\xe0y. \\nC\xe1c phe ph\xe1i kh\xe1c trong V\xe0nh Đai Văn Minh đều biết rằng Endfield đang nắm một qu\xe2n \xe1t chủ b\xe0i v\xf4 c\xf9ng đặc biệt, nhưng đ\xf3 cũng l\xe0 tất cả những g\xec họ biết. \\nSự th\xf4ng thạo đầy b\xed ẩn của Endmin đối với Originium v\xe0 Mạng Lưới Giao Thức c\xf9ng nhu cầu ngủ đ\xf4ng d\xe0i hạn định kỳ l\xe0 một trong những b\xed mật cốt l\xf5i của Endfield.","prof":"guard","elem":"physic","cv":{"en-us":"Hyoie O\'Grady"}},{"key":"endministrator1","name":"Endministrator","codename":"Endministrator","camp":"Tập Đo\xe0n Endfield","race":"Kh\xf4ng Tiết Lộ","rarity":6,"intro":"Endministrator của Tập Đo\xe0n Endfield.\\nTrong lịch sử ghi ch\xe9p của Talos-II, Endministrator được xem l\xe0 vệ binh then chốt, người đ\xe3 che chở cho nền văn minh tr\xean h\xe0nh tinh n\xe0y v\xe0 cứu nh\xe2n loại tho\xe1t khỏi v\xf4 số thảm họa diệt vong. Những chiến c\xf4ng hiển h\xe1ch của Endmin đ\xe3 tạo n\xean v\xf4 số c\xe2u chuyện, truyền thuyết v\xe0 cả những lời đồn đại. \\nThế nhưng, th\xe2n phận thật sự của Endmin vẫn l\xe0 ẩn số, chỉ một số \xedt người từng tận mắt chứng kiến huyền thoại sống n\xe0y. \\nC\xe1c phe ph\xe1i kh\xe1c trong V\xe0nh Đai Văn Minh đều biết rằng Endfield đang nắm một qu\xe2n \xe1t chủ b\xe0i v\xf4 c\xf9ng đặc biệt, nhưng đ\xf3 cũng l\xe0 tất cả những g\xec họ biết. \\nSự th\xf4ng thạo đầy b\xed ẩn của Endmin đối với Originium v\xe0 Mạng Lưới Giao Thức c\xf9ng nhu cầu ngủ đ\xf4ng d\xe0i hạn định kỳ l\xe0 một trong những b\xed mật cốt l\xf5i của Endfield.","prof":"guard","elem":"physic","cv":{"en-us":"Chloe Eves"}},{"key":"perlica","name":"Perlica","codename":"Perlica","camp":"Tập Đo\xe0n Endfield","race":"Liberi","rarity":5,"intro":"\\"Ch\xfang t\xf4i chiến đấu kh\xf4ng ngừng nghỉ... bởi v\xec ch\xfang t\xf4i tin ng\xe0i sẽ quay trở lại.\\" \\nPerlica l\xe0 Gi\xe1m S\xe1t Vi\xean của Tập Đo\xe0n Endfield, đồng thời l\xe0 người ph\xe1t ng\xf4n ch\xednh thức của tổ chức. C\xf4 chịu tr\xe1ch nhiệm ch\xednh trong việc dẫn dắt v\xe0 th\xfac đẩy sự ph\xe1t triển cũng như ứng dụng c\xf4ng nghệ Giao Thức Originium, đồng thời quản l\xfd hoạt động của Dijiang. \\nL\xe0 một chuy\xean gia xuất ch\xfang về Giao Thức C\xf4ng Nghệ, Perlica đ\xe3 ti\xean phong trong c\xe1c nghi\xean cứu mang t\xednh đột ph\xe1, định h\xecnh sự ph\xe1t triển v\xe0 ứng dụng linh hoạt của c\xf4ng nghệ n\xe0y, đồng thời ho\xe0n thiện Khu Phức Hợp C\xf4ng Nghiệp Tự Động (Nh\xe0 M\xe1y Khu Phức Hợp). \\nC\xf4 lu\xf4n b\xecnh tĩnh v\xe0 quyết đo\xe1n khi đối mặt với mọi khủng hoảng. Tuy nhi\xean, Endministrator thường phải đương đầu với những thử th\xe1ch vượt qu\xe1 mọi dự đo\xe1n. Trong thời gian Endministrator ngủ đ\xf4ng, Perlica đ\xe3 đảm nhận vai tr\xf2 chỉ huy Đội Ứng Ph\xf3 Nguy Cảnh, dẫn dắt c\xe1c anh h\xf9ng của Tập Đo\xe0n Endfield trong cuộc chiến v\xec một l\xfd tưởng vĩ đại. Kh\xf4ng ngừng nghỉ, Perlica rong ruổi khắp V\xe0nh Đai Văn Minh, l\xe0m tất cả để duy tr\xec trật tự v\xe0 vận h\xe0nh mọi thứ trơn tru. \\n\\n\\"Chỉ khi đặt ch\xe2n l\xean mảnh đất n\xe0y, ta mới thực sự cảm nhận được nhịp thở v\xe0 mạch sống nơi đ\xe2y... V\xe0 đ\xf3 ch\xednh l\xe0 điều m\xe0 Endfield đang đấu tranh.\\"","prof":"caster","elem":"electric","cv":{"en-us":"Jane Jackson"}},{"key":"chen","name":"Chen Qianyu","codename":"Chen Qianyu","camp":"Tập Đo\xe0n Endfield","race":"Lung","rarity":5,"intro":"\\"Ch\xe0, ra l\xe0 ngo\xe0i v\xf5 thuật t\xf4i c\xf2n giỏi thứ kh\xe1c nữa. Thế n\xe0y th\xec tr\xe1nh sao được danh hiệu c\xe1n vi\xean xuất sắc nhất\\". \\nChen Qianyu l\xe0 c\xe1n vi\xean tại Tập Đo\xe0n Endfield, th\xe0nh vi\xean cốt c\xe1n của Đội Ứng Ph\xf3 Nguy Cảnh. \\nTừ nhỏ, c\xf4 đ\xe3 được mẹ v\xe0 Đ\xe0m Kiếm Đường hướng dẫn luyện v\xf5. Sự ki\xean tr\xec đ\xe3 t\xf4i luyện cho c\xf4 kỹ năng chiến đấu si\xeau ph\xe0m v\xe0 \xfd ch\xed th\xe9p hiếm thấy giữa những người c\xf9ng thế hệ. D\xf9 chưa từng diện kiến Chi Xiao huyền thoại, c\xf4 vẫn tự h\xe0o ph\xe1t triển v\xe0 sử dụng Kiếm Thuật Chi Xiao của ri\xeang m\xecnh, chiến đấu v\xec ch\xednh nghĩa. \\nSau nhiều năm cầm kiếm độc h\xe0nh tr\xean Talos-II, Chen Qianyu gia nhập Endfield theo lời mời của Perlica. T\xednh c\xe1ch lạc quan v\xe0 ngọn lửa nhiệt huyết m\xe3nh liệt th\xfac đẩy c\xf4 lao v\xe0o mọi thử th\xe1ch khẩn cấp m\xe0 kh\xf4ng ch\xfat do dự. \\n\\n\\"Endmin \xe0, người ta n\xf3i lưỡi kiếm của mẹ t\xf4i c\xf3 thể khuấy động cả những đ\xe1m m\xe2y. V\xe0 t\xf4i sẽ l\xe0m được điều đ\xf3... trở th\xe0nh người đ\xe1ng để ng\xe0i v\xe0 Perlica tin cậy!\\"","prof":"guard","elem":"physic","cv":{"en-us":"Rebecca Hanssen"}},{"key":"laevatain","name":"Laevatain","codename":"Laevatain","camp":"Rhodes Island","race":"Sarkaz","rarity":6,"intro":"\\"Ho\xe0ng h\xf4n sẽ thi\xeau rụi!\\" \\nLaevatain, c\xe1n vi\xean thuộc Rhodes Island, gia nhập Endfield theo lời tiến cử trực tiếp của Endministrator. Dưới hiệp định hợp t\xe1c giữa hai tổ chức, c\xf4 phục vụ trực tiếp dưới quyền chỉ huy của Endministrator. \\nTrước khi đến với Tập Đo\xe0n Endfield, Laevatain từng đơn độc rong ruổi khắp Talos-II để theo đuổi mục ti\xeau ri\xeang. Với kỹ năng chiến đấu độc lập xuất sắc, c\xf4 thường bị lầm tưởng l\xe0 \\"kẻ kh\xf3 gần\\". Thực tế lại ho\xe0n to\xe0n tr\xe1i ngược. Chỉ l\xe0 bản chất ch\xe2n th\xe0nh, thẳng thắn của c\xf4 đ\xf4i khi thể hiện qu\xe1 r\xf5, dẫn đến hiểu lầm. \\nĐ\xf4i l\xfac, c\xf4 n\xf3i về \\"k\xfd ức\\" một c\xe1ch b\xed ẩn, như thể cố \xfd giấu đi con người thật của m\xecnh. \\nC\xf4 điều khiển ngọn lửa thuần thục, nhưng lại m\xea ăn kem lạnh v\xf4 c\xf9ng. Với Laevatain, sự m\xe2u thuẫn ấy dường như l\xe0 điều tự nhi\xean. \\n\\n\\"Nếu vẫn thấy lạnh h\xe3y gần t\xf4i xem sao\\".","prof":"assault","elem":"fire","cv":{"en-us":"Kira Buckland"}},{"key":"yvonne","name":"Yvonne","codename":"Yvonne","camp":"Tập Đo\xe0n Endfield","race":"Vouivre","rarity":6,"intro":"\\"Cặp s\xfang lục n\xe0y vừa tay lắm! Hừm... T\xf4i vừa ph\xe1t hiện v\xe0i điểm c\xf3 thể cải tiến thiết kế. Th\xf4i th\xec chỉnh lại th\xe0nh phi\xean bản đặc biệt của Yvonne vậy!\\" \\nYvonne, c\xe1n vi\xean thuộc Đội Chuy\xean Vi\xean Kỹ Thuật của Tập Đo\xe0n Endfield, hiện phụ tr\xe1ch nghi\xean cứu về \xc6ther, Nhiễm Khuẩn v\xe0 c\xe1c thiết bị li\xean quan. \\nThoạt nh\xecn, Yvonne tựa như một t\xedn đồ thời trang nổi loạn với sừng, đu\xf4i v\xe0 m\xf3ng tay rực rỡ sắc m\xe0u. C\xf4 sẵn s\xe0ng bỏ qua c\xe1c hội nghị học thuật để săn l\xf9ng tạp ch\xed thời trang mới nhất hay album nhạc thịnh h\xe0nh. Lu\xf4n bị cuốn h\xfat bởi những g\xec mới mẻ v\xe0 kh\xe1c biệt, Yvonne c\xf3 biệt t\xe0i dẫn đầu xu hướng, bước đi theo nhịp điệu ri\xeang. \\nNhưng chẳng ai phủ nhận c\xf4 l\xe0 một thi\xean t\xe0i. Ngay từ thời học đường, c\xf4 đ\xe3 gom về v\xf4 số giải thưởng nghi\xean cứu khoa học m\xe0 người kh\xe1c chỉ d\xe1m mơ. Ai cũng nghĩ c\xf4 sẽ gia nhập một học viện đỉnh cao, dẫn dắt lĩnh vực của m\xecnh. Thế nhưng, Yvonne quay lưng với tất cả để chọn gia nhập Endfield. \\nL\xfd do ư? C\xf4 chưa từng h\xe9 lộ. Nếu muốn biết, c\xf3 lẽ ng\xe0i n\xean tự hỏi c\xf4 ấy. \\n\\n\\"T\xf4i c\xf3 thể sơn lại trang bị của m\xecnh kh\xf4ng? M\xe0u hiện tại kh\xf4ng hợp với t\xf3c t\xf4i lắm\\".","prof":"assault","elem":"ice","cv":{"en-us":"Clare Louise Connolly"}},{"key":"gilberta","name":"Gilberta","codename":"Gilberta","camp":"Rhodes Island","race":"Vulpo","rarity":6,"intro":"\\"Ch\xe0o ng\xe0i nh\xe9! Ồ, ng\xe0i tỏa ra hương thơm dịu d\xe0ng của k\xfd ức tươi đẹp... như một bức thư dang dở gửi đến một nơi thật đặc biệt. T\xf4i tự hỏi nơi đ\xf3 l\xe0 đ\xe2u nhỉ\\". \\nGilberta, c\xe1n vi\xean thuộc Rhodes Island, được ph\xe2n c\xf4ng đến Tập Đo\xe0n Endfield theo hiệp định hợp t\xe1c giữa hai tổ chức. C\xf4 đảm nhiệm vai tr\xf2 Li\xean Lạc Vi\xean trong Đội Chuy\xean Vi\xean Kỹ Thuật, th\xe0nh thạo một dạng Thuật Ph\xe1p Originium hiếm c\xf3, cho ph\xe9p c\xf4 điều khiển trọng lực xung quanh. \\nTại Endfield, Gilberta phụ tr\xe1ch việc chuyển giao thư từ v\xe0 tin tức t\xecnh b\xe1o qua c\xe1c căn cứ v\xe0 tiền đồn. Nhiệm vụ thường đưa c\xf4 đến ranh giới giữa V\xe0nh Đai Văn Minh v\xe0 tiền tuyến, nhưng c\xf4 dường như say m\xea nhiệm vụ n\xe0y. Gần đ\xe2y, c\xf4 c\xf2n chủ động xin đảm nhận những nhiệm vụ nguy hiểm hơn ở c\xe1c khu vực rủi ro cao để r\xe8n giũa kỹ năng. \\nWarfarin từng thừa nhận, sự lạc quan của Gilberta, h\xf2a quyện với ch\xfat bất an v\xe0 niềm hy vọng về tương lai, đ\xe3 từng khiến c\xf4 vừa ngạc nhi\xean vừa c\xf3 ch\xfat ho\xe0i niệm. \\n\\n\\"Nh\xecn n\xe0y! C\xf4 N\xe0ng Li\xean Lạc Vi\xean Bay Bổng mang đến một bức thư đặc biệt cho ng\xe0i đấy!\\"","prof":"support","elem":"nature","cv":{"en-us":"Anna Devlin"}},{"key":"ardelia","name":"Ardelia","codename":"Ardelia","camp":"Rhodes Island","race":"Caprinae","rarity":6,"intro":"\\"Thế giới n\xe0y c\xf3 qu\xe1 nhiều điều b\xed ẩn cần kh\xe1m ph\xe1. Ch\xfang ta n\xean t\xecm hiểu về n\xf3 nhiều hơn, cũng giống như... c\xe1ch ch\xfang ta n\xean t\xecm hiểu th\xeam về ch\xednh m\xecnh. Đồng \xfd kh\xf4ng, Gi\xe1o sư?\\" \\nArdelia, c\xe1n vi\xean thuộc Rhodes Island, được ph\xe2n c\xf4ng tới Tập Đo\xe0n Endfield đảm nhận vai tr\xf2 chuy\xean gia địa chất theo thỏa thuận hợp t\xe1c giữa hai b\xean. \\nBan đầu, nghi\xean cứu của c\xf4 tập trung v\xe0o n\xfai lửa, nhưng nay đ\xe3 mở rộng sang v\xf9ng \xc6therside v\xe0 c\xe1c thảm họa địa chất. C\xf4 d\xe0nh phần lớn thời gian ngo\xe0i thực địa, một m\xecnh dấn th\xe2n v\xe0o những v\xf9ng đất bị t\xe0n ph\xe1 để thu thập mẫu vật, ph\xe2n t\xedch cấu tr\xfac v\xe0 x\xe2y dựng c\xe1c l\xfd thuyết trở th\xe0nh nền tảng cho c\xe1c biện ph\xe1p chống Nhiễm Khuẩn của Endfield. \\nLu\xf4n khi\xeam nhường v\xe0 tinh tế, Ardelia mang trong m\xecnh sức mạnh nội t\xe2m dường như bất tận. Với c\xf4, hạnh ph\xfac thật giản dị: chinh phục một ngọn n\xfai mới, bước đi tr\xean một con đường mới, lắng nghe tiếng th\xec thầm của thế giới v\xe0 lật mở những kỳ quan ẩn giấu của h\xe0nh tinh n\xe0y. \\nV\xe0 nếu ng\xe0i c\xf3 thể trở th\xe0nh tri kỷ của Ardelia, th\xec Ng\xe0i Dolly chắc chắn cũng sẽ qu\xfd mến ng\xe0i. \\n\\n\\"Ng\xe0i Dolly? Đừng bỏ chạy! Đến ch\xe0o Gi\xe1o sư n\xe0o\\".","prof":"support","elem":"nature","cv":{"en-us":"Lindsay Sheppard"}},{"key":"ember","name":"Ember","codename":"Ember","camp":"Hội Lời Thề Th\xe9p","race":"Sankta","rarity":6,"intro":"\\"L\xean đường th\xf4i. Chiến tranh chẳng bao giờ kết th\xfac. Ch\xfang ta chỉ c\xf3 thể tiếp tục tiến bước.\\" \\nEmber phục vụ trong Hội Lời Thề Th\xe9p, một đạo qu\xe2n đ\xf3ng tại v\xf9ng đất băng gi\xe1 phương bắc quanh năm. Để t\xecm người kế nhiệm cho những đồng đội đ\xe3 hy sinh, c\xf4 trở về V\xe0nh Đai Văn Minh v\xe0 chấp nhận lời mời gia nhập Tập Đo\xe0n Endfield. \\nL\xe0 tinh anh của Đơn Vị Đột K\xedch thuộc Hội Lời Thề Th\xe9p, Ember chiến đấu với kỹ năng si\xeau ph\xe0m. C\xf4 dẫn đầu mọi mũi xung k\xedch, x\xe9 tan h\xe0ng ngũ địch như một ngọn gi\xe1o bất khả x\xe2m ph\xe1. Với kẻ th\xf9, c\xf4 l\xe0 ph\xe1o đ\xe0i bất diệt. Với đồng minh, c\xf4 l\xe0 bức tường kh\xf4ng bao giờ sụp đổ. Hội Lời Thề Th\xe9p c\xf3 thể dựa v\xe0o ph\xe1o đ\xe0i v\xe0 chiến hạm, nhưng những chiến binh như Ember mới l\xe0 linh hồn của họ. \\n\\n\\"Dưới \xe1nh aurora l\xe0 những tuyến ph\xf2ng thủ của những Kỵ Sĩ Hội Lời Thề Th\xe9p.\\"","prof":"shielder","elem":"fire","cv":{"en-us":"Rhiannon Moushall"}},{"key":"lastrite","name":"Last Rite","codename":"Last Rite","camp":"Seš\'qa","race":"Sarkaz","rarity":6,"intro":"\\"C\xf3 vẻ... t\xf4i c\xf3 li\xean quan g\xec đ\xf3 đến chiến tranh?\\" \\nTrước khi được người Sarkaz của th\xe0nh phố nổi t\xecm ra, Last Rite từng l\xe0 một c\xf4 g\xe1i dịu d\xe0ng được đ\xf4i vợ chồng tr\xf4ng mộ Caprinae nhận nu\xf4i. Dưới sự uốn nắn của họ, c\xf4 g\xe1i Nachzehrer trẻ tuổi kh\xf4ng c\xf2n xới tung x\xe1c chết, k\xecm n\xe9n bản năng ăn thịt. Nhưng sự kiềm chế ấy khiến c\xf4 ch\xecm trong cơn đ\xf3i khắc khoải v\xe0 sự bất an khiến c\xf4 xa l\xe1nh mọi người. \\nMột cuộc gặp gỡ định mệnh đ\xe3 h\xe9 lộ tiềm năng của Last Rite cho Seš\'qa. V\xec tin v\xe0o lời hứa về \\"c\xf4ng việc ngắn ng\xe0y lương cao\\" v\xe0 \\"huấn luyện để chế ngự bản năng,\\" c\xf4 được c\xe1c thương nh\xe2n quen mặt gọi l\xe0 C\xf4ng Ch\xfaa của T\xf2a \xc1n Chiến Tranh. Giờ đ\xe2y, kho\xe1c l\xean m\xecnh bộ gi\xe1p nguy\xean mẫu Witching Hour, c\xf4 điều khiển băng gi\xe1 v\xe0 th\xe9p v\xec sự nghiệp của Tập Đo\xe0n Endfield – vừa để ho\xe0n th\xe0nh hợp đồng, vừa để vươn tới tương lai h\xf2a b\xecnh m\xe0 Endfield vạch ra.\\n\\n\\"Nếu hợp đồng của t\xf4i với Seš’qa hết hạn, ng\xe0i c\xf3 thể li\xean lạc với t\xf4i… \xd4i kh\xf4ng! T\xf4i kh\xf4ng n\xean n\xf3i ra điều đ\xf3! L\xe0m ơn... đừng n\xf3i với ai về chuyện n\xe0y nh\xe9...\\"","prof":"assault","elem":"ice","cv":{"en-us":"Amber Hood"}},{"key":"lifeng","name":"Lifeng","codename":"Lifeng","camp":"Học Viện Khoa Học Hongshan","race":"Anasa","rarity":6,"intro":"\\"T\xf4i đến Endfield để học hỏi. Nhưng... c\xf3 qu\xe1 nhiều thứ cần học. T\xf4i sẽ nỗ lực hết m\xecnh\\" \\nLifeng, sinh ra tại Th\xe0nh Phố V\xf5 Lăng, hiện l\xe0 thực tập sinh tại Đội Chuy\xean Vi\xean Kỹ Thuật của Tập Đo\xe0n Endfield. \\nỞ V\xf5 Lăng, Lifeng được y\xeau mến với danh xưng \\"Thủ Lĩnh Nh\xed\\". Qua nhiều năm, Da Pan đ\xe3 r\xe8n giũa kỹ năng thương thuật cho cậu, chuẩn bị cho h\xe0nh tr\xecnh đi t\xecm c\xf4ng l\xfd. \xcdt ai ngờ, đằng sau nụ cười rạng rỡ l\xe0 mảng tối đ\xe8 n\xe9n l\xean cậu: một tai nạn đ\xe3 ph\xe1 vỡ gia đ\xecnh hạnh ph\xfac của cậu, khiến cậu mất đi một c\xe1nh tay. Nhưng nghịch cảnh chẳng thể quật ng\xe3 cậu. Với tr\xe1i tim ch\xe2n th\xe0nh v\xe0 ngọn lửa nhiệt huyết, Lifeng kh\xf4ng ngừng vươn l\xean, kh\xe1t khao ng\xe0y c\xf3 thể g\xe1nh v\xe1c những trọng tr\xe1ch lớn lao. Một ng\xe0y n\xe0o đ\xf3, cậu sẽ đứng vững tr\xean đ\xf4i ch\xe2n m\xecnh, trở về che chở cho m\xe1i ấm đang chờ đợi. \\n\\n\\"Một ng\xe0y n\xe0o đ\xf3, t\xf4i sẽ đủ khả năng đảm nhận những nhiệm vụ kh\xf3 nhất. Xin h\xe3y chờ đợi ng\xe0y đ\xf3, Endmin.\\"","prof":"guard","elem":"physic","cv":{"en-us":"Yung-I Chang"}},{"key":"pogranichnik","name":"Pogranichnik","codename":"Pogranichnik","camp":"Rhodes Island","race":"Liberi","rarity":6,"intro":"\\"T\xecnh h\xecnh rất cấp b\xe1ch. T\xf4i tr\xe2n trọng đề nghị ng\xe0i t\xf3m tắt kế hoạch t\xe1c chiến của m\xecnh trong thời gian sớm nhất\\". \\nPogranichnik, c\xe1n vi\xean thuộc Rhodes Island được ph\xe2n c\xf4ng đến Tập Đo\xe0n Endfield, đảm nhận vai tr\xf2 cố vấn qu\xe2n sự theo thỏa thuận hợp t\xe1c giữa hai b\xean. \\n￼Với kiến thức uy\xean th\xe2m về l\xfd thuyết qu\xe2n sự v\xe0 kinh nghiệm chiến đấu đồng đội được t\xf4i luyện qua gian kh\xf3, anh dẫn dắt đơn vị vượt qua những khủng hoảng bất ngờ nhất. Từng l\xe0 chỉ huy của Đơn Vị Khi\xean Vệ thuộc Hội Lời Thề Th\xe9p, Pogranichnik c\xf9ng c\xe1c chiến binh của m\xecnh được t\xf4n vinh l\xe0 lực lượng đ\xe1ng tin cậy nhất tr\xean chiến tuyến chống lại Aggeloi. Khi t\xecnh h\xecnh tr\xean Talos-II ng\xe0y c\xe0ng rối loạn, anh kh\xf4ng ch\xfat do dự gia nhập Tập Đo\xe0n Endfield. Với niềm tin m\xe3nh liệt, anh tin rằng Endministrator sẽ dẫn dắt Talos-II mở ra một con đường mới, đ\xfang như kh\xe1t vọng anh từng ấp ủ. \\n\\n\\"Endmin, t\xf4i tin chắc rằng h\xe0nh động của cậu sẽ đặt dấu chấm hết cho v\xf2ng xo\xe1y chiến tranh v\xe0 hy sinh t\xe0n khốc n\xe0y\\".","prof":"vanguard","elem":"physic","cv":{"en-us":"Sergey Ponomaryov"}},{"key":"alesh","name":"Alesh","codename":"Alesh","camp":"Đại C\xf4ng Đo\xe0n Talos II","race":"Anaty","rarity":5,"intro":"\\"Bạn lu\xf4n c\xf3 thể vớt lại mồi đ\xe3 thả khi c\xe2u c\xe1. Nhưng ngo\xe0i đời, chẳng c\xf3 lối tho\xe1t dễ d\xe0ng n\xe0o khi gặp chuyện đ\xe2u.\\" \\nĐược một người li\xean lạc từ Cục An Ninh của Đại C\xf4ng Đo\xe0n tiến cử, Alesh gia nhập Tập Đo\xe0n Endfield để đảm nhận c\xf4ng t\xe1c truyền tin v\xe0 yểm trợ ở v\xf9ng tiền tuyến. Khi kh\xf4ng l\xe0m nhiệm vụ, anh ki\xeam lu\xf4n vai tr\xf2 người hướng dẫn lớp c\xe2u c\xe1 của Endfield. \\nAlesh chẳng mặn m\xe0 kể về qu\xe1 khứ \\"tẻ nhạt\\" của m\xecnh. Chỉ biết rằng anh từng lăn lộn trong tầng lớp thấp k\xe9m của v\xf9ng bi\xean cương, đối mặt với giao tranh v\xe0 phản bội ở mọi bước đường. Cuối c\xf9ng, anh rời bỏ đường phố với một b\xean mắt m\xf9 v\xe0 cơ thể kiệt quệ v\xec gi\xf3 sương. \\nNghề tay tr\xe1i của Alesh l\xe0 bu\xf4n b\xe1n c\xe1, ng\xe0y ng\xe0y đắm m\xecnh trong th\xfa vui c\xe2u c\xe1. Nhưng đằng sau vẻ ngo\xe0i điềm tĩnh ấy l\xe0 bản năng sắc b\xe9n v\xe0 \xf3c ph\xe1n đo\xe1n tinh tường. Trong l\xfac nguy cấp, \xe1nh mắt anh sắc như lưỡi c\xe2u, với v\xf4 số m\xe1nh kh\xf3e xử l\xfd rắc rối chẳng k\xe9m g\xec kỹ thuật k\xe9o mồi. Khi l\xe0m nhiệm vụ, anh vẫn giữ nụ cười ung dung, mang về những chiến thắng ngo\xe0i sức tưởng tượng. \\n\\n\\"Sống một cuộc đời hạnh ph\xfac l\xe0 điều quan trọng. Lời khuy\xean ch\xe2n th\xe0nh từ một người gi\xe0 dặn đấy Endmin \xe0.\\"","prof":"vanguard","elem":"ice","cv":{"en-us":"Heitor Assali"}},{"key":"arclight","name":"Arclight","codename":"Arclight","camp":"Trường Địa Hannabit","race":"Kuranta","rarity":5,"intro":"\\"T\xf4i l\xe0 Ekut. Biệt danh Arclight. Tuy kh\xf4ng kh\xe9o ăn n\xf3i nhưng t\xf4i xin ch\xfac c\xe1c nh\xe2n vi\xean Endfield mọi điều tốt l\xe0nh v\xe0 thuận buồm xu\xf4i gi\xf3\\". \\nArclight, biệt danh Kẻ Tầm Ca, gia nhập Tập Đo\xe0n Endfield theo lời tiến cử của Đạo Sư Orisha. C\xf4 hiện l\xe0 c\xe1n vi\xean thực địa ki\xeam cố vấn kỹ thuật về m\xe1y m\xf3c v\xe0 phương tiện. \\nKh\xf4ng ai lang bạt tr\xean hoang địa c\xf3 thể tho\xe1t khỏi m\xf3ng vuốt của nạn đ\xf3i v\xe0 thảm họa, d\xf9 họ tự cho m\xecnh th\xf4ng th\xe1i hay bản lĩnh đến đ\xe2u. Bất hạnh đ\xe3 gi\xe1ng xuống Arclight như lưỡi dao sắc. Hoang Địa cướp đi cả gia tộc c\xf4, để lại c\xf4 l\xe0 người duy nhất sống s\xf3t. Song, vận may đ\xe3 mỉm cười khi một nh\xf3m Kẻ Tầm Ca của Trường Địa Hannabit đ\xe3 t\xecm thấy v\xe0 cứu c\xf4 khỏi bờ vực tử thần. \\nTrường Địa Hannabit đ\xe3 dang tay ch\xe0o đ\xf3n c\xf4. Tại đ\xf3, c\xf4 nhanh ch\xf3ng nắm vững c\xe1ch sinh tồn trong cảnh khắc nghiệt v\xe0 noi theo gương c\xe1c Mẫu Mực từ b\xe0i ca dao, gi\xfap đỡ những kẻ khốn c\xf9ng. Giờ đ\xe2y, c\xf4 rong ruổi khắp Hoang Địa, truyền dạy b\xed quyết sinh tồn trong thế giới t\xe0n khốc của Talos-II cho nhiều linh hồn hơn. \\nThoạt nh\xecn, Arclight c\xf3 thể lạnh l\xf9ng v\xe0 cộc lốc, nhưng triết l\xfd tối giản của c\xf4 đ\xe3 chứng tỏ hiệu quả vượt trội để tồn tại giữa Hoang Địa. \\n\\n\\"Sửa chữa một chiến m\xe3 sắt cũng giống như điều trị một con T\xea Gi\xe1c Bướu. Cần lắng nghe thật kỹ trước khi ra tay\\".","prof":"vanguard","elem":"electric","cv":{"en-us":"Andrea Gatchalian"}},{"key":"avywenna","name":"Avywenna","codename":"Avywenna","camp":"Ph\xf2ng Thương Mại Tổng Hợp Talos-II","race":"Cautus","rarity":5,"intro":"\\"Li\xean lạc vi\xean như t\xf4i phải chuyển ph\xe1t kh\xf4ng \xedt b\xed mật đến nơi an to\xe0n, m\xe0 b\xed mật n\xe0o cũng đi k\xe8m c\xe1i gi\xe1 đắt đỏ. Nhưng c\xf2n thứ đắt hơn cả chi ph\xed giao h\xe0ng, đ\xf3 l\xe0... việc t\xf4i k\xedn miệng đối với những b\xed mật đ\xf3.\\" \\nAvywenna l\xe0 Li\xean Lạc Vi\xean Vũ Trang. \\nTrước khi gia nhập Tập Đo\xe0n Endfield, c\xf4 từng sống c\xf9ng một gia đ\xecnh quyền lực trong ng\xe0nh vận chuyển tại Th\xe0nh Phố Tự Do Alloycarrot. Song, ngọn lửa phi\xeau lưu trong huyết quản đ\xe3 th\xfac đẩy c\xf4 rời bỏ cuộc sống đ\xf3 để dấn th\xe2n v\xe0o h\xe0nh tr\xecnh ri\xeang. Qua những miền đất tr\xean khắp Talos-II, c\xf4 ph\xe1t hiện một sợi d\xe2y li\xean kết tất cả, đ\xf3 l\xe0 b\xf3ng h\xecnh b\xed ẩn của Endministrator. \\nAvywenna tỏa s\xe1ng trong c\xe1c mối giao thiệp, xử l\xfd mọi mối quan hệ một c\xe1ch ch\xedn chắn v\xe0 kh\xe9o l\xe9o. Nhưng liệu c\xf4 c\xf3 thực sự h\xf2a nh\xe3 như vẻ ngo\xe0i? Chỉ khi đối diện c\xf4 ấy, bạn mới t\xecm ra c\xe2u trả lời. \\n\\n\\"Chẳng ai th\xedch bị khi\xeau kh\xedch cả... n\xean nếu c\xf3 thể n\xf3i chuyện cho ra lẽ th\xec t\xf4i th\xedch vậy hơn l\xe0 động tay ch\xe2n. Nhưng n\xf3i trước, t\xf4i cũng kh\xf4ng dễ để người kh\xe1c l\xean mặt đ\xe2u.\\"","prof":"assault","elem":"electric","cv":{"en-us":"Sheena May"}},{"key":"dapan","name":"Da Pan","codename":"Da Pan","camp":"Học Viện Khoa Học Hongshan","race":"Ursus","rarity":5,"intro":"\\"Nếu kh\xf4ng giỏi nấu m\xf3n g\xec th\xec cứ nấu m\xf3n đ\xf3 thật nhiều lần! T\xf4i kh\xf4ng nấu ăn để khoe khoang! T\xf4i nấu để tạo ra một bữa tiệc thật đẹp v\xe0 vui vẻ!\\" \\nDa Pan xuất th\xe2n từ Học Viện Khoa Học Hongshan danh tiếng nhưng lại rời bỏ chốn ấy để dấn th\xe2n v\xe0o v\xf4 số vai tr\xf2 hậu cần đa dạng, từ đầu bếp, thợ điện, t\xe0i xế, đến người b\xe1n rong. Bước ngoặt mới nhất của anh? Gia nhập Đội Chuy\xean Vi\xean Kỹ Thuật của Tập Đo\xe0n Endfield với tư c\xe1ch nh\xe2n vi\xean tự do. \\nTrong mu\xf4n v\xe0n vai tr\xf2 từng đảm nhận, anh tự h\xe0o nhất khi l\xe0 một đầu bếp du h\xe0nh. Đam m\xea kh\xe1m ph\xe1 c\xf4ng thức mới v\xe0 s\xe1ng tạo những m\xf3n ăn độc đ\xe1o, kh\xf4ng g\xec khiến Da Pan hạnh ph\xfac hơn khi chế biến những bữa ăn ngon l\xe0nh, khiến mọi thực kh\xe1ch phải trầm trồ. \\nAnh lu\xf4n mang theo một b\xecnh nước, thứ \xedt ai để \xfd. Người đọc được chữ Vi\xeam c\xf3 thể t\xf2 m\xf2 về nguồn gốc của n\xf3. Nhưng nếu họ đến từ Hongshan, họ sẽ nhận ra ngay – đ\xf3 l\xe0 biểu tượng vinh dự chỉ d\xe0nh cho c\xe1c Nh\xe0 Khoa Học Ti\xean Phong. \\n\\n\\"Thử đi. T\xf4i tự nấu đấy!\\"","prof":"assault","elem":"physic","cv":{"en-us":"Jon Xu"}},{"key":"snowshine","name":"Snowshine","codename":"Snowshine","camp":"Rhodes Island","race":"Ursus","rarity":5,"intro":"\\"Gi\xf3 vừa phải. Tầm nh\xecn tốt. Thời tiết l\xfd tưởng để trượt tuyết đấy\\". \\nSnowshine l\xe0 c\xe1n vi\xean thuộc Rhodes Island được ph\xe2n c\xf4ng đến Tập Đo\xe0n Endfield để đảm nhiệm vai tr\xf2 chuy\xean gia t\xecm kiếm v\xe0 cứu nạn (SAR) theo hiệp định hợp t\xe1c giữa hai tổ chức. \\nV\xec những l\xfd do ai cũng r\xf5, c\xe1c v\xf9ng cực đ\xedch thực của Talos-II vẫn l\xe0 chốn cấm đối với nh\xe2n loại. Song, khi dự \xe1n mở rộng bi\xean cương được tiếp tục, những chuy\xean gia như Snowshine, am hiểu địa l\xfd v\xf9ng cực v\xe0 cao nguy\xean, ng\xe0y c\xe0ng được trọng dụng tại V\xe0nh Đai Văn Minh. \\nDo khan hiếm nh\xe2n t\xe0i, Snowshine v\xe0 đội cứu hộ của c\xf4 lu\xf4n bận rộn, kể cả trong những ng\xe0y kh\xf4ng c\xf3 nhiệm vụ đặc biệt. \\nD\xf9 lịch tr\xecnh d\xe0y đặc, c\xf4 vẫn d\xe0nh thời gian rảnh để viết Cẩm Nang Sinh Tồn V\xf9ng Cực, cuốn s\xe1ch giờ đ\xe2y trở th\xe0nh t\xe0i liệu chủ chốt cho c\xe1c hoạt động sinh tồn v\xe0 cứu nạn trong m\xf4i trường băng tuyết khắc nghiệt của Talos-II. \\n\\n\\"T\xf4i th\xedch tuyết, những ngọn n\xfai trắng phủ đầy tuyết, v\xe0 vẻ đẹp lấp l\xe1nh chỉ hiện ra trong c\xe1i lạnh cắt da cắt thịt… Đ\xe2y l\xe0 l\xfd do t\xf4i kh\xf4ng muốn họ để lại những k\xfd ức đau thương cho những người m\xe0 họ chạm tới\\".","prof":"shielder","elem":"ice","cv":{"en-us":"Stephanie Southerland"}},{"key":"wulfgard","name":"Wulfgard","codename":"Wulfgard","camp":"Tập Đo\xe0n Endfield","race":"Lupo","rarity":5,"intro":"\\"T\xf4i biết sức mạnh kh\xf4ng phải l\xe0 tất cả, nhưng ở đất Talos-II m\xe0 kh\xf4ng c\xf3 sức mạnh th\xec kh\xf3 sống.\\" \\nCatello Wulfgard Luppino, l\xednh đ\xe1nh thu\xea trẻ tuổi sống ở r\xeca V\xe0nh Đai Văn Minh, hiện l\xe0m việc cho Đội Ứng Ph\xf3 Nguy Cảnh tại Tập Đo\xe0n Endfield.\\nD\xf9 c\xf2n trẻ, Wulfgard đ\xe3 hiểu r\xf5 bản chất dễ thay l\xf2ng đổi dạ của con người. Nhưng những chuyện ấy kh\xf4ng l\xe0m cậu gục ng\xe3, tr\xe1i lại c\xe0ng khiến cậu ch\xedn chắn vượt trội hẳn so với độ tuổi. Cậu kh\xf4ng chủ động g\xe2y sự m\xe0 khi thấy c\xf3 biến, cậu chọn tr\xe1nh đối đầu trực diện. Với t\xe0i năng trong t\xe1c chiến t\xe0ng h\xecnh v\xe0 trinh s\xe1t, Wulfgard c\xf3 thể đi s\xe1t b\xean kẻ th\xf9, chờ thời cơ tung đ\xf2n ch\xed tử khi ch\xfang \xedt ngờ tới nhất. \\nL\xe0 th\xe0nh vi\xean của tộc Landbreaker, biệt danh Băng Nh\xf3m Pack, Wulfgard l\xe0 đồng minh đ\xe1ng tin cậy nếu bạn chinh phục được l\xf2ng tin của cậu ta. Nhưng đ\xf3 l\xe0 thử th\xe1ch kh\xf4ng hề đơn giản. \\n\\n\\"Chủ nghĩa l\xfd tưởng phi thực tế ph\xe1 hủy nhiều cuộc đời hơn l\xe0 cứu rỗi.\\"","prof":"caster","elem":"fire","cv":{"en-us":"Jacopo Calatroni"}},{"key":"xaihi","name":"Xaihi","codename":"Xaihi","camp":"Tu Hội Tĩnh Lặng","race":"Sarkaz","rarity":5,"intro":"\\"Một khi ta đo\xe0n kết, cơ mưu sẽ sinh khởi.\\" \\nXaihi, xuất th\xe2n từ Tu Hội Tĩnh Lặng l\xe0 tổ chức nghi\xean cứu được Lateran ph\xe1i đến Talos-II để kh\xe1m ph\xe1 c\xf4ng nghệ. L\xe0 người theo chủ nghĩa Hội Luận, c\xf4 tin rằng t\xednh to\xe1n v\xe0 ph\xe2n t\xedch ng\xf4n ngữ sẽ dẫn lối đến Ch\xe2n L\xfd. \\nC\xf4 giao tiếp với m\xe1y m\xf3c thuần thục hơn l\xe0 với con người. T\xe0i năng xuất ch\xfang trong c\xf4ng nghệ th\xf4ng tin của c\xf4 được ch\xednh Nữ Viện Trưởng của Đại Tu Viện trong Tu Hội Tĩnh Lặng c\xf4ng nhận. D\xf9 việc n\xe2ng cấp \\"tr\xe1i ph\xe9p\\" m\xe1i v\xf2m của Gi\xe1o Đường từng g\xe2y ra h\xe0ng loạt sự cố, Nữ Viện Trưởng vẫn hết l\xf2ng tiến cử c\xf4 đến Tập Đo\xe0n Endfield, hy vọng c\xf4 t\xecm được nơi xứng tầm để thể hiện t\xe0i năng. \\nGiờ đ\xe2y, Xaihi l\xe0m việc tr\xean t\xe0u Dijiang, đảm nhiệm c\xe1c nhiệm vụ kỹ thuật th\xf4ng tin như x\xe2y dựng Mạng Lưới Protorig v\xe0 t\xedch hợp hệ thống. Những hiểu biết độc đ\xe1o về Mạng Lưới Originium, kết hợp với tri thức s\xe2u sắc từ Tu Hội, khiến c\xf4 trở th\xe0nh một th\xe0nh vi\xean kh\xf4ng thể thiếu của Endfield. \\n\\n\\"\xd4i Tri Thức cổ xưa nhất, xin đừng dẫn ch\xfang t\xf4i v\xe0o c\xe1m dỗ m\xe0 h\xe3y giải tho\xe1t ch\xfang t\xf4i khỏi m\xe3 độc hại… Thưa Endministrator, t\xf4i l\xe0 Xaihi. Xin h\xe3y soi s\xe1ng cho t\xf4i.\\"","prof":"support","elem":"ice","cv":{"en-us":"Elsie Lovelock"}},{"key":"akekuri","name":"Akekuri","codename":"Akekuri","camp":"Tập Đo\xe0n Endfield","race":"Perro","rarity":4,"intro":"\\"Akekuri, Đội Z7, b\xe1o c\xe1o! Thật h\xe1o hức khi được tham gia nhiệm vụ, ho\xe0n th\xe0nh xuất sắc nh\xe9!\\" \\nAkekuri, Đội trưởng Đội T\xe1c Chiến Z7 thuộc Đội Chuy\xean Vi\xean Kỹ Thuật, nổi tiếng với nụ cười rạng rỡ v\xe0 c\xe2u n\xf3i đặc trưng: \\"Để t\xf4i lo.\\" Từ hoạch định chiến lược đến quản l\xfd thường nhật, c\xf4 nắm trọn mọi việc. Vượt xa t\xe0i năng chỉ huy chiến thuật, Akekuri l\xe0 bậc thầy phối hợp, lu\xf4n t\xecm ra giải ph\xe1p tối ưu d\xf9 nguồn lực khan hiếm. C\xf4 c\xf2n kh\xe9o l\xe9o chăm lo đội nh\xf3m, đảm bảo mọi th\xe0nh vi\xean h\xf2a hợp v\xe0 tỏa s\xe1ng ở vị tr\xed th\xedch hợp nhất. \\nĐội T\xe1c Chiến Z7 gần như do ch\xednh c\xf4 x\xe2y dựng từ con số kh\xf4ng. Chỉ trong v\xe0i th\xe1ng, c\xf4 chi\xeau mộ, huấn luyện, v\xe0 triển khai đội, dẫn dắt họ đạt những th\xe0nh t\xedch lẫy lừng. Nghĩ m\xe0 xem, chẳng bao l\xe2u trước, c\xf4 chỉ l\xe0 một học vi\xean xuất sắc từ Học Viện Kinh Doanh, tự nguyện gia nhập Endfield. Ai ngờ một t\xe2n binh lại vươn l\xean thần tốc, trở th\xe0nh đội trưởng đ\xe1ng tin cậy tuyệt đối. \\nNếu bạn từng t\xf2 m\xf2 về ngọn lửa đam m\xea, l\xfd tưởng, hay ước nguyện giản dị khiến c\xf4 kh\xf4ng ngừng tiến bước th\xec… \\n\\n\\"Giải lao c\xe0 ph\xea chứ Endmin? T\xf4i c\xf3 thể pha cho cậu một t\xe1ch c\xe0 ph\xea mới!\\"","prof":"vanguard","elem":"fire","cv":{"en-us":"Shu Uchida"}},{"key":"antal","name":"Antal","codename":"Antal","camp":"Tập Đo\xe0n Endfield","race":"Savra","rarity":4,"intro":"\\"Nhiệm vụ cho t\xf4i \xe0? Tuyệt. Đ\xfang l\xfac t\xf4i cũng đang t\xecm cơ hội thử nghiệm thực địa cho t\xe0u quỹ đạo cải tiến.\\" \\nAntal, th\xe0nh vi\xean của Đội T\xe1c Chiến Z7 tại Endfield, đảm tr\xe1ch vai tr\xf2 người hỗ trợ v\xe0 cố vấn c\xf4ng nghệ Originium. Th\xf4ng minh v\xe0 nhanh tr\xed, nhưng anh lại vụng về trong việc thấu hiểu l\xf2ng người. Kh\xf4ng \xedt lần, những lời nhận x\xe9t lạc l\xf5ng của anh khiến cả đội thở d\xe0i ngao ng\xe1n. D\xf9 vậy, t\xe0i năng về Thuật Ph\xe1p Originium của anh v\xf4 c\xf9ng xuất ch\xfang, d\xf9 ch\xednh anh dường như chẳng hay biết. \\nChịu ảnh hưởng từ b\xe0, Antal thờ ơ với những th\xe0nh c\xf4ng tầm thường, dồn trọn t\xe2m huyết v\xe0o bất cứ điều g\xec khơi dậy đam m\xea. D\xf9 l\xe0 một thiết bị Originium chưa từng thấy hay một c\xe2u đ\xf9a kh\xf4 khốc khiến anh trầm trồ, ch\xe0ng Savra trẻ tuổi n\xe0y sẽ kh\xf4ng ngừng nghỉ cho đến khi lật mở mọi b\xed ẩn. \\n\\n\\"Thật kỳ lạ, sự xuất hiện của ng\xe0i lại c\xe0ng l\xe0m tăng khao kh\xe1t chia sẻ kho kiến thức rộng lớn của t\xf4i.\\"","prof":"support","elem":"electric","cv":{"en-us":"Jacob Craner"}},{"key":"catcher","name":"Catcher","codename":"Catcher","camp":"Tập Đo\xe0n Endfield","race":"Perro","rarity":4,"intro":"\\"Cần yểm trợ ph\xf2ng thủ? T\xf4i sẽ dốc to\xe0n lực.\\" \\nCatcher phục vụ trong Đội T\xe1c Chiến Z7 tại Endfield, đảm tr\xe1ch vai tr\xf2 hậu cần v\xe0 yểm trợ. Với nền tảng huấn luyện qu\xe2n sự b\xe0i bản, anh vận dụng kiến thức uy\xean th\xe2m để dẫn dắt đồng đội vượt qua những thời khắc sinh tử. Sinh ra trong một gia đ\xecnh qu\xe2n nh\xe2n thuộc Ph\xf2ng Thương Mại Tổng Hợp Talos-II, Catcher lớn l\xean trong v\xf2ng tay y\xeau thương của cha mẹ v\xe0 anh chị. Nỗi đau v\xe0 bệnh tật từ một tai nạn thời thơ ấu chẳng thể quật ng\xe3 anh, m\xe0 ngược lại, đ\xe3 t\xf4i luyện anh th\xe0nh một chiến binh ki\xean định như h\xf4m nay. \\nD\xf9 l\xe0 th\xe0nh vi\xean trẻ nhất đội, sự ch\xedn chắn của Catcher vượt xa những người đồng trang lứa. Anh h\xf2a nhịp ho\xe0n hảo với mọi người, sẵn s\xe0ng che chắn khi đồng đội gặp kh\xf3 v\xe0 c\xf2n chuẩn bị những bữa ăn trại tỉ mỉ đ\xe1p ứng nhu cầu của từng th\xe0nh vi\xean. C\xf3 Catcher b\xean cạnh, cả đội lu\xf4n cảm thấy an to\xe0n v\xe0 y\xean t\xe2m. \\n\\n\\"Gần đ\xe2y t\xf4i đ\xe3 xem x\xe9t tất cả gợi \xfd v\xe0 cải tiến c\xf4ng thức hầm ngo\xe0i hoang địa... Nếu t\xf2 m\xf2, cứ thử nếm xem nh\xe9, Endmin.\\"","prof":"shielder","elem":"physic","cv":{"en-us":"Kevin Andrew Rivera"}},{"key":"estella","name":"Estella","codename":"Estella","camp":"Tập Đo\xe0n Endfield","race":"Feline","rarity":4,"intro":"\\"Hừ... Cảm gi\xe1c như cả thế giới đang đ\xe8 nặng l\xean người m\xecnh… đặc biệt l\xe0 đầu gối…\\" \\nEstella, th\xe0nh vi\xean của Đội T\xe1c Chiến Z7 tại Endfield, đảm tr\xe1ch nhiệm vụ thu thập t\xecnh b\xe1o v\xe0 truyền tin. Thể chất yếu ớt, lu\xf4n bị b\xf3ng đen bất hạnh b\xe1m theo, c\xf4 thường d\xf9ng lưỡi dao sắc b\xe9n của lời n\xf3i v\xe0 khiếu h\xe0i hước u \xe1m để giữ khoảng c\xe1ch với người ngo\xe0i. Ước mơ của c\xf4 giản dị: một cuộc sống an y\xean. Bởi lẽ, c\xf4 đ\xe3 chứng kiến qu\xe1 nhiều người như m\xecnh, mắc kẹt trong một thế giới kh\xf4ng lối tho\xe1t, kh\xf4ng đổi thay, kh\xf4ng tương lai. \\nCuộc đời đầy hiểm nguy v\xe0 cực đoan đ\xe3 l\xe0m chai sạn gi\xe1c quan của c\xf4, n\xe2ng ngưỡng cảm x\xfac l\xean cao. V\xec thế, c\xf4 đ\xf4i khi t\xecm đến những thử th\xe1ch khắc nghiệt hơn – như tiếng g\xe0o th\xe9t của d\xf2ng nhạc rock heavy metal dữ dội – để cảm nhận ch\xfat thay đổi tho\xe1ng qua, ch\xfat g\xec đ\xf3 ch\xe2n thực. Những c\xfa k\xedch hiếm hoi đ\xf3 mang lại cho c\xf4 cảm gi\xe1c thay đổi tho\xe1ng qua v\xe0 điều g\xec đ\xf3 thật sự. \\nQua c\xf4ng việc tại Endfield, Estella khao kh\xe1t khiến thế giới tốt đẹp hơn, d\xf9 chỉ một ch\xfat v\xe0 mang lại ch\xfat nhẹ nh\xe0ng cho những người xung quanh. \\n\\n\\"M\xecnh lại l\xe0m việc qu\xe1 sức rồi… Hừ… Tốt hơn hết l\xe0 n\xean tr\xe2n trọng khoảng thời gian nghỉ ngơi n\xe0y.\\"","prof":"guard","elem":"ice","cv":{"en-us":"Risa Mei"}},{"key":"fluorite","name":"Fluorite","codename":"Fluorite","camp":"Tập Đo\xe0n Endfield","race":"Phidia","rarity":4,"intro":"\\"Đ\xe1nh lạc hướng ch\xfang? V\xf4 hiệu h\xf3a ch\xfang? Hay... chỉ cần ti\xeau diệt ch\xfang?\\" \\nL\xe0 th\xe0nh vi\xean của Đội T\xe1c Chiến Z7 tại Endfield, Fluorite chịu tr\xe1ch nhiệm trinh s\xe1t v\xe0 ph\xe1 vỡ ph\xf2ng tuyến của kẻ th\xf9. C\xf4 th\xe0nh thạo luật đường phố v\xe0 những m\xe1nh kh\xf3e bẩn thỉu, ngang ngửa với t\xe0i bắn tỉa đi\xeau luyện, gi\xfap cả đội tr\xe1nh khỏi v\xf4 số rắc rối. Xuất th\xe2n từ v\xf9ng tiền tuyến của V\xe0nh Đai Văn Minh, c\xf4 đ\xe3 m\xe0i giũa đ\xf4i mắt của m\xecnh qua những chuyến di cư v\xe0 lang thang li\xean tục. Thường th\xec c\xf4 chỉ ngồi một g\xf3c với nụ cười nhẹ, khiến người kh\xe1c c\xf3 cảm gi\xe1c bất an rằng mọi khuyết điểm đ\xe3 bị phơi b\xe0y dưới \xe1nh mắt của c\xf4. \\nNhưng đừng nhầm lẫn c\xf4 với sự đồng cảm. Khả năng đọc vị người kh\xe1c của Fluorite mang lại cho c\xf4 những bản năng đặc biệt tr\xean chiến trường, nhưng cũng khiến c\xf4 cực kỳ giỏi trong việc k\xedch động người kh\xe1c chỉ bằng v\xe0i lời n\xf3i — khiến c\xf4 trở th\xe0nh nguồn rắc rối kh\xf3 lường nhất của đội. \\n\\n\\"C\xf3 điều g\xec muốn n\xf3i kh\xf4ng? Kh\xf4ng hả? Vậy ch\xfang ta kết th\xfac cho h\xf4m nay đi?\\"","prof":"caster","elem":"nature","cv":{"en-us":"Katiana Sarkissian"}}]'),h={SansMedium:'\n        url("'.concat(n(10414),'") format("woff2"),\n        url("').concat(n(84726),'") format("woff"),\n        url("').concat(n(20544),'") format("truetype"),\n    '),SansBold:'\n        url("'.concat(n(74738),'") format("woff2"),\n        url("').concat(n(33922),'") format("woff"),\n        url("').concat(n(29804),'") format("truetype"),\n    '),SansBlack:'\n        url("'.concat(n(30610),'") format("woff2"),\n        url("').concat(n(33058),'") format("woff"),\n        url("').concat(n(7404),'") format("truetype"),\n    '),SansRegular:'\n        url("'.concat(n(89095),'") format("woff2"),\n        url("').concat(n(90149),'") format("woff"),\n        url("').concat(n(2085),'") format("truetype"),\n    ')},p=JSON.parse('{"aic.items.0.description":"Khu Phức Hợp C\xf4ng Nghiệp Tự Động mạnh mẽ của Tập Đo\xe0n Endfield cho ph\xe9p sản xuất tự động hiệu quả nhiều loại thiết bị, thuốc nổ, pin, vật dụng chiến thuật v\xe0 c\xe1c vật liệu kh\xe1c.","aic.items.0.title":"Sản Xuất Tự Động","aic.items.1.description":"L\xf5i Tự Động H\xf3a Giao Thức l\xe0 một trong những th\xe0nh tựu c\xf4ng nghệ cốt l\xf5i của Endfield. Sử dụng Giao Thức Dịch Chuyển, L\xf5i Giao Thức c\xf3 thể \\"in\\" ra nhiều c\xf4ng tr\xecnh v\xe0 mở rộng c\xf4ng nghệ Khu Phức Hợp đến mọi ng\xf3c ng\xe1ch của Talos-II.","aic.items.1.title":"L\xf5i Tự Động H\xf3a Giao Thức","aic.items.2.description":"Tập Đo\xe0n Endfield sử dụng c\xe1c đơn vị vận chuyển mạnh mẽ như Băng Tải Vận Chuyển, Van T\xe1ch v\xe0 Tổng Tuyến Kho H\xe0ng. Đ\xe2y l\xe0 những yếu tố thiết yếu để nhanh ch\xf3ng thiết lập c\xe1c d\xe2y chuyền sản xuất tự động.","aic.items.2.title":"Hệ Thống Vận Chuyển","aic.items.3.description":"Tập Đo\xe0n Endfield sử dụng Th\xe1p Tiếp Điện v\xe0 Cột Điện để ph\xe2n phối điện từ L\xd5I GIAO THỨC đến c\xe1c cơ sở được kết nối. Điều n\xe0y gi\xfap d\xf2ng điện li\xean tục v\xe0 c\xe1c c\xf4ng tr\xecnh hoạt động tự động h\xf3a sản xuất.","aic.items.3.title":"Hệ Thống Điện Năng","aic.items.4.description":"Nh\xe0 M\xe1y Khu Phức Hợp tại V\xf5 Lăng c\xf3 c\xe1c c\xf4ng tr\xecnh mới để thu thập v\xe0 xử l\xfd nhiều loại chất lỏng kh\xe1c nhau, cho ph\xe9p sản xuất h\xe0ng loạt loại vật liệu đặc biệt c\xf3 t\xean l\xe0 Xiranite. Sau khi được lắp đặt, Th\xe1p Tiếp Điện Xiranite v\xe0 Cột Xiranite do Học Viện Khoa Học Hongshan ph\xe1t triển sẽ tự động kết nối với lưới điện hiện c\xf3 v\xe0 cung cấp điện cho c\xe1c cơ sở l\xe2n cận.","aic.items.4.title":"Sơ Đồ KPH V\xf5 Lăng","common.back":"Quay lại","common.latest":"Mới Nhất","common.selectLanguage":"Chọn ng\xf4n ngữ","gameplay.items.0.description":"Phi\xeau lưu v\xe0o những d\xe3y n\xfai cao ch\xf3t v\xf3t v\xe0 những d\xf2ng s\xf4ng quanh co của Talos-II. Ti\xeau diệt Nhiễm Khuẩn v\xe0 v\xf4 hiệu h\xf3a c\xe1c mối đe dọa từ Ankhor. Dẫn dắt Tập Đo\xe0n Endfield mở rộng khắp h\xe0nh tinh khi bạn x\xe2y dựng v\xe0 ph\xe1t triển từng khu vực tr\xean đường đi.","gameplay.items.0.title":"Kh\xe1m ph\xe1 Talos-II","gameplay.items.1.description":"Dẫn dắt đội của bạn v\xe0o trận chiến, phối hợp nhịp nh\xe0ng v\xe0 tung ra c\xe1c kỹ năng li\xean ho\xe0n để đ\xe1nh bại mọi loại kẻ địch. C\xf9ng nhau s\xe1t c\xe1nh bảo vệ qu\xea hương Talos-II.","gameplay.items.1.title":"Đội Chiến Đấu","gameplay.items.2.description":"Sử dụng nhiều c\xf4ng tr\xecnh Endfield kh\xe1c nhau để x\xe2y dựng d\xe2y chuyền sản xuất tự động. L\xe0m theo bản vẽ hoặc tự do x\xe2y dựng để sản xuất mọi thứ, từ thiết bị v\xe0 chất nổ đến thực phẩm v\xe0 thuốc men, nhằm hỗ trợ qu\xe1 tr\xecnh mở rộng li\xean tục.","gameplay.items.2.title":"X\xe2y dựng Nh\xe0 M\xe1y Khu Phức Hợp","gameplay.items.3.description":"Duy tr\xec hoạt động trơn tru của trụ sở Tập Đo\xe0n Endfield. X\xe2y dựng v\xe0 n\xe2ng cấp nhiều khoang kh\xe1c nhau, tương t\xe1c với c\xe1n vi\xean để tạo dựng niềm tin, giới thiệu th\xe0nh t\xedch của bạn tại Ph\xf2ng Tiếp Kh\xe1ch, v\xe0 đ\xf3n tiếp kh\xe1ch hoặc đến thăm những người kh\xe1c.","gameplay.items.3.title":"Quản l\xfd Tập Đo\xe0n Endfield","header.charge":"Trung T\xe2m Nạp","header.creator":"Người tạo","header.login":"Đăng nhập","header.mute.off":"\xc2m thanh: Mở","header.mute.on":"\xc2m thanh: Tắt","header.user":"T\xe0i khoản","home.activity":"Đ\xe3 Nạp Đầy!","home.actPreGacha":"R\xfat thẻ sớm","home.download":"Tải xuống","home.fillQuestionnaire":"Beta Sign-Up","home.questionnaireDisabled":"Đ\xe3 nộp khảo s\xe1t","home.reserve":"Đăng k\xfd trước","home.themeSite":"Triển L\xe3m Chủ Đề","home.title":"Đương L\xfac Xu\xe2n Th\xec","home.title.v1d4":"Về Nh\xe0","home.title1.v1d4":"Phi\xean Bản cho Chương Ch\xednh","home.title2.v1d4":"V\xf5 Lăng Quyết Chiến","home.title3.v1d4":"T\xe1i Ngộ, C\xf9ng Bước Sang Chương Mới","information.cate.CHARACTER":"Giới Thiệu Nh\xe2n Vật","information.cate.SPECIAL":"Trailer Đặc Biệt","information.cate.VERSION":"Trailer Phi\xean Bản","information.displayTimeFormat":"DD-MM-YYYY","information.more":"Th\xeam video","landing.downloadNow":"Tải Ngay","landing.frontInfo":"OVER THE FRONTIER / INTO THE FRONT","landing.gameDesc":"3D即时策略RPG游戏","landing.welcome":"Phi\xean Bản Mới Ra Mắt","lore.models.anchor.codename":"ANKHOR","lore.models.anchor.intro":"Ankhor l\xe0 những cấu tr\xfac b\xed ẩn k\xedch hoạt sự h\xecnh th\xe0nh Aggeloi. Nguồn gốc của ch\xfang vẫn chưa được biết r\xf5, v\xe0 ch\xfang ph\xe2n t\xe1n ngẫu nhi\xean khắp Talos-II. Khi đ\xe1p xuống, ch\xfang bắt đầu h\xfat c\xe1c vật liệu tự nhi\xean gần đ\xf3 để li\xean tục tạo ra Aggeloi.","lore.models.anchor.name":"Ankhor","lore.models.enemy.codename":"LANDBREAKER","lore.models.enemy.intro":"Landbreaker thường \xe1m chỉ những nh\xf3m cướp c\xf3 vũ trang ở r\xeca x\xe3 hội kiếm sống bằng nghề cướp b\xf3c hoặc c\xe1c h\xecnh thức bạo lực tội phạm kh\xe1c. Khi giấc mộng chinh phạt của bọn Landbreaker tan vỡ, băng nh\xf3m n\xe0y t\xe1ch ra th\xe0nh nhiều nh\xf3m kh\xe1c nhau. Mỗi nh\xf3m giờ mang một c\xe1i t\xean ri\xeang, nhưng người ta vẫn d\xf9ng \\"Landbreaker\\" như một thuật ngữ chung cho bất kỳ nh\xf3m vũ trang n\xe0o đứng l\xean chống lại trật tự văn minh.","lore.models.enemy.name":"Landbreaker","lore.models.factory.codename":"AIC","lore.models.factory.intro":"Khu Phức Hợp C\xf4ng Nghiệp Tự Động (Khu Phức Hợp) l\xe0 một trong những c\xf4ng nghệ chủ chốt của Tập Đo\xe0n Endfield.  N\xf3 đại diện cho qu\xe1 tr\xecnh thu nhỏ v\xe0 m\xf4-đun h\xf3a m\xe1y m\xf3c sản xuất c\xf4ng nghiệp th\xe0nh c\xf4ng. Một nh\xf3m nhỏ chuy\xean gia được trang bị c\xf4ng nghệ Khu Phức Hợp c\xf3 thể nhanh ch\xf3ng triển khai một d\xe2y chuyền sản xuất tự động ho\xe0n chỉnh.","lore.models.factory.name":"Khu Phức Hợp C\xf4ng Nghiệp Tự Động","lore.models.pile.codename":"TIANSHI PILLAR","lore.models.pile.intro":"Cột Thi\xean Sư l\xe0 những thiết bị Xiranite h\xecnh cột được ph\xe1t triển để đối ph\xf3 với Triều Nhiễm Khuẩn, đại diện cho một trong những th\xe0nh tựu khoa học vĩ đại của Học Viện Khoa Học Hongshan. Bằng c\xe1ch kết hợp c\xf4ng nghệ Originium với nghi\xean cứu Cự Th\xfa, nh\xf3m Thi\xean Sư của Học Viện đ\xe3 ph\xe1t minh Cột Thi\xean Sư để chống lại Triều Nhiễm Khuẩn. Thiết bị n\xe0y ph\xf3ng c\xe1c hạt Xiranite v\xe0 k\xedch hoạt ch\xfang khi cần thiết để l\xe0m suy yếu t\xe1c động của Nhiễm Khuẩn.","lore.models.pile.name":"Cột Thi\xean Sư","lore.models.spaceship.codename":"DIJIANG","lore.models.spaceship.intro":"T\xe0u Vũ Trụ Originium Dijiang l\xe0 t\xe0u vũ trụ bay tr\xean quỹ đạo địa tĩnh nh\xe2n tạo ph\xeda tr\xean Talos-II. Đ\xe2y l\xe0 trụ sở hiện tại của Tập Đo\xe0n Endfield.  Được hỗ trợ bởi l\xf5i lớn của Giao Thức Originium, n\xf3 hỗ trợ nhiều hệ thống con kh\xe1c nhau, bao gồm Giao Thức Dịch Chuyển (TP) v\xe0 Khu Phức Hợp C\xf4ng Nghiệp Tự Động.","lore.models.spaceship.name":"Dijiang","lore.models.trinity.codename":"AGGELOID","lore.models.trinity.intro":"Aggelos (số nhiều: Aggeloi) chỉ mọi thực thể th\xf9 địch c\xf3 sự sống được cấu th\xe0nh từ vật chất tự nhi\xean v\xe0 một cấu tr\xfac vầng s\xe1ng, được tạo ra bởi một Ankhor th\xf4ng qua qu\xe1 tr\xecnh kiến tạo x\xfac t\xe1c. Trong suốt lịch sử mở rộng của nh\xe2n loại tr\xean khắp Talos-II, Aggeloi lu\xf4n l\xe0 mối đe dọa ch\xednh của ch\xfang ta. Cuộc Chiến Aggeloi được đặt theo t\xean kẻ địch của nh\xe2n loại.","lore.models.trinity.name":"Aggeloi","modal.user.currentUser":"T\xe0i khoản hiện tại","modal.user.logout":"Đăng Xuất","modal.user.title":"Th\xf4ng Tin T\xe0i Khoản","modal.user.userCenter":"Trung T\xe2m T\xe0i Khoản","nav.aic":"Th\xf4ng Tin Nh\xe0 M\xe1y Khu Phức Hợp","nav.calendar":"Lịch Tr\xecnh Phi\xean Bản","nav.gameplay":"Lối Chơi","nav.home":"Trang Chủ","nav.information":"Truyền Th\xf4ng","nav.lore":"Truyền Sử","nav.milestone":"Mốc Đăng K\xfd Trước","nav.notice":"Tin Tức","nav.operator":"C\xe1n Vi\xean","nav.preserveNow":"Đăng k\xfd trước ngay","nav.preserveNowShort":"Đăng k\xfd trước ngay","notice.detail":"Th\xf4ng Tin Kh\xe1c","notice.tab.events":"Sự Kiện","notice.tab.news":"Tin Tức","notice.tab.notices":"Th\xf4ng B\xe1o","operator.camp":"Phe","operator.camps.0":"Tập Đo\xe0n Endfield","operator.camps.1":"Trường Địa Hannabit","operator.camps.2":"Hội Lời Thề Th\xe9p","operator.camps.3":"Tu Hội Tĩnh Lặng","operator.camps.4":"Ph\xf2ng Thương Mại Tổng Hợp Talos-II","operator.camps.5":"Rhodes Island","operator.camps.6":"Học Viện Khoa Học Hongshan","operator.camps.7":"Đại C\xf4ng Đo\xe0n Talos II","operator.camps.8":"Seš\'qa","operator.content.akekuri.intro":"\\"Akekuri, Đội Z7, b\xe1o c\xe1o! Thật h\xe1o hức khi được tham gia nhiệm vụ, ho\xe0n th\xe0nh xuất sắc nh\xe9!\\"  Akekuri, Đội trưởng Đội T\xe1c Chiến Z7 thuộc Đội Chuy\xean Vi\xean Kỹ Thuật, nổi tiếng với nụ cười rạng rỡ v\xe0 c\xe2u n\xf3i đặc trưng: \\"Để t\xf4i lo.\\" Từ hoạch định chiến lược đến quản l\xfd thường nhật, c\xf4 nắm trọn mọi việc. Vượt xa t\xe0i năng chỉ huy chiến thuật, Akekuri l\xe0 bậc thầy phối hợp, lu\xf4n t\xecm ra giải ph\xe1p tối ưu d\xf9 nguồn lực khan hiếm. C\xf4 c\xf2n kh\xe9o l\xe9o chăm lo đội nh\xf3m, đảm bảo mọi th\xe0nh vi\xean h\xf2a hợp v\xe0 tỏa s\xe1ng ở vị tr\xed th\xedch hợp nhất.  Đội T\xe1c Chiến Z7 gần như do ch\xednh c\xf4 x\xe2y dựng từ con số kh\xf4ng. Chỉ trong v\xe0i th\xe1ng, c\xf4 chi\xeau mộ, huấn luyện, v\xe0 triển khai đội, dẫn dắt họ đạt những th\xe0nh t\xedch lẫy lừng. Nghĩ m\xe0 xem, chẳng bao l\xe2u trước, c\xf4 chỉ l\xe0 một học vi\xean xuất sắc từ Học Viện Kinh Doanh, tự nguyện gia nhập Endfield. Ai ngờ một t\xe2n binh lại vươn l\xean thần tốc, trở th\xe0nh đội trưởng đ\xe1ng tin cậy tuyệt đối.  Nếu bạn từng t\xf2 m\xf2 về ngọn lửa đam m\xea, l\xfd tưởng, hay ước nguyện giản dị khiến c\xf4 kh\xf4ng ngừng tiến bước th\xec…  \\n \\"Giải lao c\xe0 ph\xea chứ Endmin? T\xf4i c\xf3 thể pha cho cậu một t\xe1ch c\xe0 ph\xea mới!\\"","operator.content.akekuri.name":"Akekuri","operator.content.alesh.intro":"\\"Bạn lu\xf4n c\xf3 thể vớt lại mồi đ\xe3 thả khi c\xe2u c\xe1. Nhưng ngo\xe0i đời, chẳng c\xf3 lối tho\xe1t dễ d\xe0ng n\xe0o khi gặp chuyện đ\xe2u.\\"  Được một người li\xean lạc từ Cục An Ninh của Đại C\xf4ng Đo\xe0n tiến cử, Alesh gia nhập Tập Đo\xe0n Endfield để đảm nhận c\xf4ng t\xe1c truyền tin v\xe0 yểm trợ ở v\xf9ng tiền tuyến. Khi kh\xf4ng l\xe0m nhiệm vụ, anh ki\xeam lu\xf4n vai tr\xf2 người hướng dẫn lớp c\xe2u c\xe1 của Endfield.  Alesh chẳng mặn m\xe0 kể về qu\xe1 khứ \\"tẻ nhạt\\" của m\xecnh. Chỉ biết rằng anh từng lăn lộn trong tầng lớp thấp k\xe9m của v\xf9ng bi\xean cương, đối mặt với giao tranh v\xe0 phản bội ở mọi bước đường. Cuối c\xf9ng, anh rời bỏ đường phố với một b\xean mắt m\xf9 v\xe0 cơ thể kiệt quệ v\xec gi\xf3 sương.  Nghề tay tr\xe1i của Alesh l\xe0 bu\xf4n b\xe1n c\xe1, ng\xe0y ng\xe0y đắm m\xecnh trong th\xfa vui c\xe2u c\xe1. Nhưng đằng sau vẻ ngo\xe0i điềm tĩnh ấy l\xe0 bản năng sắc b\xe9n v\xe0 \xf3c ph\xe1n đo\xe1n tinh tường. Trong l\xfac nguy cấp, \xe1nh mắt anh sắc như lưỡi c\xe2u, với v\xf4 số m\xe1nh kh\xf3e xử l\xfd rắc rối chẳng k\xe9m g\xec kỹ thuật k\xe9o mồi. Khi l\xe0m nhiệm vụ, anh vẫn giữ nụ cười ung dung, mang về những chiến thắng ngo\xe0i sức tưởng tượng.  \\n \\"Sống một cuộc đời hạnh ph\xfac l\xe0 điều quan trọng. Lời khuy\xean ch\xe2n th\xe0nh từ một người gi\xe0 dặn đấy Endmin \xe0.\\"","operator.content.alesh.name":"Alesh","operator.content.antal.intro":"\\"Nhiệm vụ cho t\xf4i \xe0? Tuyệt. Đ\xfang l\xfac t\xf4i cũng đang t\xecm cơ hội thử nghiệm thực địa cho t\xe0u quỹ đạo cải tiến.\\"  Antal, th\xe0nh vi\xean của Đội T\xe1c Chiến Z7 tại Endfield, đảm tr\xe1ch vai tr\xf2 người hỗ trợ v\xe0 cố vấn c\xf4ng nghệ Originium. Th\xf4ng minh v\xe0 nhanh tr\xed, nhưng anh lại vụng về trong việc thấu hiểu l\xf2ng người. Kh\xf4ng \xedt lần, những lời nhận x\xe9t lạc l\xf5ng của anh khiến cả đội thở d\xe0i ngao ng\xe1n. D\xf9 vậy, t\xe0i năng về Thuật Ph\xe1p Originium của anh v\xf4 c\xf9ng xuất ch\xfang, d\xf9 ch\xednh anh dường như chẳng hay biết.  Chịu ảnh hưởng từ b\xe0, Antal thờ ơ với những th\xe0nh c\xf4ng tầm thường, dồn trọn t\xe2m huyết v\xe0o bất cứ điều g\xec khơi dậy đam m\xea. D\xf9 l\xe0 một thiết bị Originium chưa từng thấy hay một c\xe2u đ\xf9a kh\xf4 khốc khiến anh trầm trồ, ch\xe0ng Savra trẻ tuổi n\xe0y sẽ kh\xf4ng ngừng nghỉ cho đến khi lật mở mọi b\xed ẩn.  \\n \\"Thật kỳ lạ, sự xuất hiện của ng\xe0i lại c\xe0ng l\xe0m tăng khao kh\xe1t chia sẻ kho kiến thức rộng lớn của t\xf4i.\\"","operator.content.antal.name":"Antal","operator.content.arclight.intro":"\\"T\xf4i l\xe0 Ekut. Biệt danh Arclight. Tuy kh\xf4ng kh\xe9o ăn n\xf3i nhưng t\xf4i xin ch\xfac c\xe1c nh\xe2n vi\xean Endfield mọi điều tốt l\xe0nh v\xe0 thuận buồm xu\xf4i gi\xf3\\".  Arclight, biệt danh Kẻ Tầm Ca, gia nhập Tập Đo\xe0n Endfield theo lời tiến cử của Đạo Sư Orisha. C\xf4 hiện l\xe0 c\xe1n vi\xean thực địa ki\xeam cố vấn kỹ thuật về m\xe1y m\xf3c v\xe0 phương tiện.  Kh\xf4ng ai lang bạt tr\xean hoang địa c\xf3 thể tho\xe1t khỏi m\xf3ng vuốt của nạn đ\xf3i v\xe0 thảm họa, d\xf9 họ tự cho m\xecnh th\xf4ng th\xe1i hay bản lĩnh đến đ\xe2u. Bất hạnh đ\xe3 gi\xe1ng xuống Arclight như lưỡi dao sắc. Hoang Địa cướp đi cả gia tộc c\xf4, để lại c\xf4 l\xe0 người duy nhất sống s\xf3t. Song, vận may đ\xe3 mỉm cười khi một nh\xf3m Kẻ Tầm Ca của Trường Địa Hannabit đ\xe3 t\xecm thấy v\xe0 cứu c\xf4 khỏi bờ vực tử thần.  Trường Địa Hannabit đ\xe3 dang tay ch\xe0o đ\xf3n c\xf4. Tại đ\xf3, c\xf4 nhanh ch\xf3ng nắm vững c\xe1ch sinh tồn trong cảnh khắc nghiệt v\xe0 noi theo gương c\xe1c Mẫu Mực từ b\xe0i ca dao, gi\xfap đỡ những kẻ khốn c\xf9ng. Giờ đ\xe2y, c\xf4 rong ruổi khắp Hoang Địa, truyền dạy b\xed quyết sinh tồn trong thế giới t\xe0n khốc của Talos-II cho nhiều linh hồn hơn.  Thoạt nh\xecn, Arclight c\xf3 thể lạnh l\xf9ng v\xe0 cộc lốc, nhưng triết l\xfd tối giản của c\xf4 đ\xe3 chứng tỏ hiệu quả vượt trội để tồn tại giữa Hoang Địa.  \\n \\"Sửa chữa một chiến m\xe3 sắt cũng giống như điều trị một con T\xea Gi\xe1c Bướu. Cần lắng nghe thật kỹ trước khi ra tay\\".","operator.content.arclight.name":"Arclight","operator.content.ardelia.intro":"\\"Thế giới n\xe0y c\xf3 qu\xe1 nhiều điều b\xed ẩn cần kh\xe1m ph\xe1. Ch\xfang ta n\xean t\xecm hiểu về n\xf3 nhiều hơn, cũng giống như... c\xe1ch ch\xfang ta n\xean t\xecm hiểu th\xeam về ch\xednh m\xecnh. Đồng \xfd kh\xf4ng, Gi\xe1o sư?\\"  Ardelia, c\xe1n vi\xean thuộc Rhodes Island, được ph\xe2n c\xf4ng tới Tập Đo\xe0n Endfield đảm nhận vai tr\xf2 chuy\xean gia địa chất theo thỏa thuận hợp t\xe1c giữa hai b\xean.  Ban đầu, nghi\xean cứu của c\xf4 tập trung v\xe0o n\xfai lửa, nhưng nay đ\xe3 mở rộng sang v\xf9ng \xc6therside v\xe0 c\xe1c thảm họa địa chất. C\xf4 d\xe0nh phần lớn thời gian ngo\xe0i thực địa, một m\xecnh dấn th\xe2n v\xe0o những v\xf9ng đất bị t\xe0n ph\xe1 để thu thập mẫu vật, ph\xe2n t\xedch cấu tr\xfac v\xe0 x\xe2y dựng c\xe1c l\xfd thuyết trở th\xe0nh nền tảng cho c\xe1c biện ph\xe1p chống Nhiễm Khuẩn của Endfield.  Lu\xf4n khi\xeam nhường v\xe0 tinh tế, Ardelia mang trong m\xecnh sức mạnh nội t\xe2m dường như bất tận. Với c\xf4, hạnh ph\xfac thật giản dị: chinh phục một ngọn n\xfai mới, bước đi tr\xean một con đường mới, lắng nghe tiếng th\xec thầm của thế giới v\xe0 lật mở những kỳ quan ẩn giấu của h\xe0nh tinh n\xe0y.  V\xe0 nếu ng\xe0i c\xf3 thể trở th\xe0nh tri kỷ của Ardelia, th\xec Ng\xe0i Dolly chắc chắn cũng sẽ qu\xfd mến ng\xe0i.  \\n \\"Ng\xe0i Dolly? Đừng bỏ chạy! Đến ch\xe0o Gi\xe1o sư n\xe0o\\".","operator.content.ardelia.name":"Ardelia","operator.content.avywenna.intro":"\\"Li\xean lạc vi\xean như t\xf4i phải chuyển ph\xe1t kh\xf4ng \xedt b\xed mật đến nơi an to\xe0n, m\xe0 b\xed mật n\xe0o cũng đi k\xe8m c\xe1i gi\xe1 đắt đỏ. Nhưng c\xf2n thứ đắt hơn cả chi ph\xed giao h\xe0ng, đ\xf3 l\xe0... việc t\xf4i k\xedn miệng đối với những b\xed mật đ\xf3.\\"  Avywenna l\xe0 Li\xean Lạc Vi\xean Vũ Trang.  Trước khi gia nhập Tập Đo\xe0n Endfield, c\xf4 từng sống c\xf9ng một gia đ\xecnh quyền lực trong ng\xe0nh vận chuyển tại Th\xe0nh Phố Tự Do Alloycarrot. Song, ngọn lửa phi\xeau lưu trong huyết quản đ\xe3 th\xfac đẩy c\xf4 rời bỏ cuộc sống đ\xf3 để dấn th\xe2n v\xe0o h\xe0nh tr\xecnh ri\xeang. Qua những miền đất tr\xean khắp Talos-II, c\xf4 ph\xe1t hiện một sợi d\xe2y li\xean kết tất cả, đ\xf3 l\xe0 b\xf3ng h\xecnh b\xed ẩn của Endministrator.  Avywenna tỏa s\xe1ng trong c\xe1c mối giao thiệp, xử l\xfd mọi mối quan hệ một c\xe1ch ch\xedn chắn v\xe0 kh\xe9o l\xe9o. Nhưng liệu c\xf4 c\xf3 thực sự h\xf2a nh\xe3 như vẻ ngo\xe0i? Chỉ khi đối diện c\xf4 ấy, bạn mới t\xecm ra c\xe2u trả lời.  \\n \\"Chẳng ai th\xedch bị khi\xeau kh\xedch cả... n\xean nếu c\xf3 thể n\xf3i chuyện cho ra lẽ th\xec t\xf4i th\xedch vậy hơn l\xe0 động tay ch\xe2n. Nhưng n\xf3i trước, t\xf4i cũng kh\xf4ng dễ để người kh\xe1c l\xean mặt đ\xe2u.\\"","operator.content.avywenna.name":"Avywenna","operator.content.catcher.intro":"\\"Cần yểm trợ ph\xf2ng thủ? T\xf4i sẽ dốc to\xe0n lực.\\"  Catcher phục vụ trong Đội T\xe1c Chiến Z7 tại Endfield, đảm tr\xe1ch vai tr\xf2 hậu cần v\xe0 yểm trợ. Với nền tảng huấn luyện qu\xe2n sự b\xe0i bản, anh vận dụng kiến thức uy\xean th\xe2m để dẫn dắt đồng đội vượt qua những thời khắc sinh tử. Sinh ra trong một gia đ\xecnh qu\xe2n nh\xe2n thuộc Ph\xf2ng Thương Mại Tổng Hợp Talos-II, Catcher lớn l\xean trong v\xf2ng tay y\xeau thương của cha mẹ v\xe0 anh chị. Nỗi đau v\xe0 bệnh tật từ một tai nạn thời thơ ấu chẳng thể quật ng\xe3 anh, m\xe0 ngược lại, đ\xe3 t\xf4i luyện anh th\xe0nh một chiến binh ki\xean định như h\xf4m nay.  D\xf9 l\xe0 th\xe0nh vi\xean trẻ nhất đội, sự ch\xedn chắn của Catcher vượt xa những người đồng trang lứa. Anh h\xf2a nhịp ho\xe0n hảo với mọi người, sẵn s\xe0ng che chắn khi đồng đội gặp kh\xf3 v\xe0 c\xf2n chuẩn bị những bữa ăn trại tỉ mỉ đ\xe1p ứng nhu cầu của từng th\xe0nh vi\xean. C\xf3 Catcher b\xean cạnh, cả đội lu\xf4n cảm thấy an to\xe0n v\xe0 y\xean t\xe2m.  \\n \\"Gần đ\xe2y t\xf4i đ\xe3 xem x\xe9t tất cả gợi \xfd v\xe0 cải tiến c\xf4ng thức hầm ngo\xe0i hoang địa... Nếu t\xf2 m\xf2, cứ thử nếm xem nh\xe9, Endmin.\\"","operator.content.catcher.name":"Catcher","operator.content.chen.intro":"\\"Ch\xe0, ra l\xe0 ngo\xe0i v\xf5 thuật t\xf4i c\xf2n giỏi thứ kh\xe1c nữa. Thế n\xe0y th\xec tr\xe1nh sao được danh hiệu c\xe1n vi\xean xuất sắc nhất\\".  Chen Qianyu l\xe0 c\xe1n vi\xean tại Tập Đo\xe0n Endfield, th\xe0nh vi\xean cốt c\xe1n của Đội Ứng Ph\xf3 Nguy Cảnh.  Từ nhỏ, c\xf4 đ\xe3 được mẹ v\xe0 Đ\xe0m Kiếm Đường hướng dẫn luyện v\xf5. Sự ki\xean tr\xec đ\xe3 t\xf4i luyện cho c\xf4 kỹ năng chiến đấu si\xeau ph\xe0m v\xe0 \xfd ch\xed th\xe9p hiếm thấy giữa những người c\xf9ng thế hệ. D\xf9 chưa từng diện kiến Chi Xiao huyền thoại, c\xf4 vẫn tự h\xe0o ph\xe1t triển v\xe0 sử dụng Kiếm Thuật Chi Xiao của ri\xeang m\xecnh, chiến đấu v\xec ch\xednh nghĩa.  Sau nhiều năm cầm kiếm độc h\xe0nh tr\xean Talos-II, Chen Qianyu gia nhập Endfield theo lời mời của Perlica. T\xednh c\xe1ch lạc quan v\xe0 ngọn lửa nhiệt huyết m\xe3nh liệt th\xfac đẩy c\xf4 lao v\xe0o mọi thử th\xe1ch khẩn cấp m\xe0 kh\xf4ng ch\xfat do dự.  \\n \\"Endmin \xe0, người ta n\xf3i lưỡi kiếm của mẹ t\xf4i c\xf3 thể khuấy động cả những đ\xe1m m\xe2y. V\xe0 t\xf4i sẽ l\xe0m được điều đ\xf3... trở th\xe0nh người đ\xe1ng để ng\xe0i v\xe0 Perlica tin cậy!\\"","operator.content.chen.name":"Chen Qianyu","operator.content.dapan.intro":"\\"Nếu kh\xf4ng giỏi nấu m\xf3n g\xec th\xec cứ nấu m\xf3n đ\xf3 thật nhiều lần! T\xf4i kh\xf4ng nấu ăn để khoe khoang! T\xf4i nấu để tạo ra một bữa tiệc thật đẹp v\xe0 vui vẻ!\\"  Da Pan xuất th\xe2n từ Học Viện Khoa Học Hongshan danh tiếng nhưng lại rời bỏ chốn ấy để dấn th\xe2n v\xe0o v\xf4 số vai tr\xf2 hậu cần đa dạng, từ đầu bếp, thợ điện, t\xe0i xế, đến người b\xe1n rong. Bước ngoặt mới nhất của anh? Gia nhập Đội Chuy\xean Vi\xean Kỹ Thuật của Tập Đo\xe0n Endfield với tư c\xe1ch nh\xe2n vi\xean tự do.  Trong mu\xf4n v\xe0n vai tr\xf2 từng đảm nhận, anh tự h\xe0o nhất khi l\xe0 một đầu bếp du h\xe0nh. Đam m\xea kh\xe1m ph\xe1 c\xf4ng thức mới v\xe0 s\xe1ng tạo những m\xf3n ăn độc đ\xe1o, kh\xf4ng g\xec khiến Da Pan hạnh ph\xfac hơn khi chế biến những bữa ăn ngon l\xe0nh, khiến mọi thực kh\xe1ch phải trầm trồ.  Anh lu\xf4n mang theo một b\xecnh nước, thứ \xedt ai để \xfd. Người đọc được chữ Vi\xeam c\xf3 thể t\xf2 m\xf2 về nguồn gốc của n\xf3. Nhưng nếu họ đến từ Hongshan, họ sẽ nhận ra ngay – đ\xf3 l\xe0 biểu tượng vinh dự chỉ d\xe0nh cho c\xe1c Nh\xe0 Khoa Học Ti\xean Phong.  \\n \\"Thử đi. T\xf4i tự nấu đấy!\\"","operator.content.dapan.name":"Da Pan","operator.content.ember.intro":"\\"L\xean đường th\xf4i. Chiến tranh chẳng bao giờ kết th\xfac. Ch\xfang ta chỉ c\xf3 thể tiếp tục tiến bước.\\"  Ember phục vụ trong Hội Lời Thề Th\xe9p, một đạo qu\xe2n đ\xf3ng tại v\xf9ng đất băng gi\xe1 phương bắc quanh năm. Để t\xecm người kế nhiệm cho những đồng đội đ\xe3 hy sinh, c\xf4 trở về V\xe0nh Đai Văn Minh v\xe0 chấp nhận lời mời gia nhập Tập Đo\xe0n Endfield.  L\xe0 tinh anh của Đơn Vị Đột K\xedch thuộc Hội Lời Thề Th\xe9p, Ember chiến đấu với kỹ năng si\xeau ph\xe0m. C\xf4 dẫn đầu mọi mũi xung k\xedch, x\xe9 tan h\xe0ng ngũ địch như một ngọn gi\xe1o bất khả x\xe2m ph\xe1. Với kẻ th\xf9, c\xf4 l\xe0 ph\xe1o đ\xe0i bất diệt. Với đồng minh, c\xf4 l\xe0 bức tường kh\xf4ng bao giờ sụp đổ. Hội Lời Thề Th\xe9p c\xf3 thể dựa v\xe0o ph\xe1o đ\xe0i v\xe0 chiến hạm, nhưng những chiến binh như Ember mới l\xe0 linh hồn của họ.  \\n \\"Dưới \xe1nh aurora l\xe0 những tuyến ph\xf2ng thủ của những Kỵ Sĩ Hội Lời Thề Th\xe9p.\\"","operator.content.ember.name":"Ember","operator.content.endministrator1.intro":"Endministrator của Tập Đo\xe0n Endfield. Trong lịch sử ghi ch\xe9p của Talos-II, Endministrator được xem l\xe0 vệ binh then chốt, người đ\xe3 che chở cho nền văn minh tr\xean h\xe0nh tinh n\xe0y v\xe0 cứu nh\xe2n loại tho\xe1t khỏi v\xf4 số thảm họa diệt vong. Những chiến c\xf4ng hiển h\xe1ch của Endmin đ\xe3 tạo n\xean v\xf4 số c\xe2u chuyện, truyền thuyết v\xe0 cả những lời đồn đại.  Thế nhưng, th\xe2n phận thật sự của Endmin vẫn l\xe0 ẩn số, chỉ một số \xedt người từng tận mắt chứng kiến huyền thoại sống n\xe0y.  C\xe1c phe ph\xe1i kh\xe1c trong V\xe0nh Đai Văn Minh đều biết rằng Endfield đang nắm một qu\xe2n \xe1t chủ b\xe0i v\xf4 c\xf9ng đặc biệt, nhưng đ\xf3 cũng l\xe0 tất cả những g\xec họ biết.  Sự th\xf4ng thạo đầy b\xed ẩn của Endmin đối với Originium v\xe0 Mạng Lưới Giao Thức c\xf9ng nhu cầu ngủ đ\xf4ng d\xe0i hạn định kỳ l\xe0 một trong những b\xed mật cốt l\xf5i của Endfield.","operator.content.endministrator1.name":"Endministrator","operator.content.endministrator2.intro":"Endministrator của Tập Đo\xe0n Endfield. Trong lịch sử ghi ch\xe9p của Talos-II, Endministrator được xem l\xe0 vệ binh then chốt, người đ\xe3 che chở cho nền văn minh tr\xean h\xe0nh tinh n\xe0y v\xe0 cứu nh\xe2n loại tho\xe1t khỏi v\xf4 số thảm họa diệt vong. Những chiến c\xf4ng hiển h\xe1ch của Endmin đ\xe3 tạo n\xean v\xf4 số c\xe2u chuyện, truyền thuyết v\xe0 cả những lời đồn đại.  Thế nhưng, th\xe2n phận thật sự của Endmin vẫn l\xe0 ẩn số, chỉ một số \xedt người từng tận mắt chứng kiến huyền thoại sống n\xe0y.  C\xe1c phe ph\xe1i kh\xe1c trong V\xe0nh Đai Văn Minh đều biết rằng Endfield đang nắm một qu\xe2n \xe1t chủ b\xe0i v\xf4 c\xf9ng đặc biệt, nhưng đ\xf3 cũng l\xe0 tất cả những g\xec họ biết.  Sự th\xf4ng thạo đầy b\xed ẩn của Endmin đối với Originium v\xe0 Mạng Lưới Giao Thức c\xf9ng nhu cầu ngủ đ\xf4ng d\xe0i hạn định kỳ l\xe0 một trong những b\xed mật cốt l\xf5i của Endfield.","operator.content.endministrator2.name":"Endministrator","operator.content.estella.intro":"\\"Hừ... Cảm gi\xe1c như cả thế giới đang đ\xe8 nặng l\xean người m\xecnh… đặc biệt l\xe0 đầu gối…\\"  Estella, th\xe0nh vi\xean của Đội T\xe1c Chiến Z7 tại Endfield, đảm tr\xe1ch nhiệm vụ thu thập t\xecnh b\xe1o v\xe0 truyền tin. Thể chất yếu ớt, lu\xf4n bị b\xf3ng đen bất hạnh b\xe1m theo, c\xf4 thường d\xf9ng lưỡi dao sắc b\xe9n của lời n\xf3i v\xe0 khiếu h\xe0i hước u \xe1m để giữ khoảng c\xe1ch với người ngo\xe0i. Ước mơ của c\xf4 giản dị: một cuộc sống an y\xean. Bởi lẽ, c\xf4 đ\xe3 chứng kiến qu\xe1 nhiều người như m\xecnh, mắc kẹt trong một thế giới kh\xf4ng lối tho\xe1t, kh\xf4ng đổi thay, kh\xf4ng tương lai.  Cuộc đời đầy hiểm nguy v\xe0 cực đoan đ\xe3 l\xe0m chai sạn gi\xe1c quan của c\xf4, n\xe2ng ngưỡng cảm x\xfac l\xean cao. V\xec thế, c\xf4 đ\xf4i khi t\xecm đến những thử th\xe1ch khắc nghiệt hơn – như tiếng g\xe0o th\xe9t của d\xf2ng nhạc rock heavy metal dữ dội – để cảm nhận ch\xfat thay đổi tho\xe1ng qua, ch\xfat g\xec đ\xf3 ch\xe2n thực. Những c\xfa k\xedch hiếm hoi đ\xf3 mang lại cho c\xf4 cảm gi\xe1c thay đổi tho\xe1ng qua v\xe0 điều g\xec đ\xf3 thật sự.  Qua c\xf4ng việc tại Endfield, Estella khao kh\xe1t khiến thế giới tốt đẹp hơn, d\xf9 chỉ một ch\xfat v\xe0 mang lại ch\xfat nhẹ nh\xe0ng cho những người xung quanh.  \\n \\"M\xecnh lại l\xe0m việc qu\xe1 sức rồi… Hừ… Tốt hơn hết l\xe0 n\xean tr\xe2n trọng khoảng thời gian nghỉ ngơi n\xe0y.\\"","operator.content.estella.name":"Estella","operator.content.fluorite.intro":"\\"Đ\xe1nh lạc hướng ch\xfang? V\xf4 hiệu h\xf3a ch\xfang? Hay... chỉ cần ti\xeau diệt ch\xfang?\\"  L\xe0 th\xe0nh vi\xean của Đội T\xe1c Chiến Z7 tại Endfield, Fluorite chịu tr\xe1ch nhiệm trinh s\xe1t v\xe0 ph\xe1 vỡ ph\xf2ng tuyến của kẻ th\xf9. C\xf4 th\xe0nh thạo luật đường phố v\xe0 những m\xe1nh kh\xf3e bẩn thỉu, ngang ngửa với t\xe0i bắn tỉa đi\xeau luyện, gi\xfap cả đội tr\xe1nh khỏi v\xf4 số rắc rối. Xuất th\xe2n từ v\xf9ng tiền tuyến của V\xe0nh Đai Văn Minh, c\xf4 đ\xe3 m\xe0i giũa đ\xf4i mắt của m\xecnh qua những chuyến di cư v\xe0 lang thang li\xean tục. Thường th\xec c\xf4 chỉ ngồi một g\xf3c với nụ cười nhẹ, khiến người kh\xe1c c\xf3 cảm gi\xe1c bất an rằng mọi khuyết điểm đ\xe3 bị phơi b\xe0y dưới \xe1nh mắt của c\xf4.  Nhưng đừng nhầm lẫn c\xf4 với sự đồng cảm. Khả năng đọc vị người kh\xe1c của Fluorite mang lại cho c\xf4 những bản năng đặc biệt tr\xean chiến trường, nhưng cũng khiến c\xf4 cực kỳ giỏi trong việc k\xedch động người kh\xe1c chỉ bằng v\xe0i lời n\xf3i — khiến c\xf4 trở th\xe0nh nguồn rắc rối kh\xf3 lường nhất của đội.  \\n \\"C\xf3 điều g\xec muốn n\xf3i kh\xf4ng? Kh\xf4ng hả? Vậy ch\xfang ta kết th\xfac cho h\xf4m nay đi?\\"","operator.content.fluorite.name":"Fluorite","operator.content.gilberta.intro":"\\"Ch\xe0o ng\xe0i nh\xe9! Ồ, ng\xe0i tỏa ra hương thơm dịu d\xe0ng của k\xfd ức tươi đẹp... như một bức thư dang dở gửi đến một nơi thật đặc biệt. T\xf4i tự hỏi nơi đ\xf3 l\xe0 đ\xe2u nhỉ\\".  Gilberta, c\xe1n vi\xean thuộc Rhodes Island, được ph\xe2n c\xf4ng đến Tập Đo\xe0n Endfield theo hiệp định hợp t\xe1c giữa hai tổ chức. C\xf4 đảm nhiệm vai tr\xf2 Li\xean Lạc Vi\xean trong Đội Chuy\xean Vi\xean Kỹ Thuật, th\xe0nh thạo một dạng Thuật Ph\xe1p Originium hiếm c\xf3, cho ph\xe9p c\xf4 điều khiển trọng lực xung quanh.  Tại Endfield, Gilberta phụ tr\xe1ch việc chuyển giao thư từ v\xe0 tin tức t\xecnh b\xe1o qua c\xe1c căn cứ v\xe0 tiền đồn. Nhiệm vụ thường đưa c\xf4 đến ranh giới giữa V\xe0nh Đai Văn Minh v\xe0 tiền tuyến, nhưng c\xf4 dường như say m\xea nhiệm vụ n\xe0y. Gần đ\xe2y, c\xf4 c\xf2n chủ động xin đảm nhận những nhiệm vụ nguy hiểm hơn ở c\xe1c khu vực rủi ro cao để r\xe8n giũa kỹ năng.  Warfarin từng thừa nhận, sự lạc quan của Gilberta, h\xf2a quyện với ch\xfat bất an v\xe0 niềm hy vọng về tương lai, đ\xe3 từng khiến c\xf4 vừa ngạc nhi\xean vừa c\xf3 ch\xfat ho\xe0i niệm.  \\n \\"Nh\xecn n\xe0y! C\xf4 N\xe0ng Li\xean Lạc Vi\xean Bay Bổng mang đến một bức thư đặc biệt cho ng\xe0i đấy!\\"","operator.content.gilberta.name":"Gilberta","operator.content.laevatain.intro":"\\"Ho\xe0ng h\xf4n sẽ thi\xeau rụi!\\"  Laevatain, c\xe1n vi\xean thuộc Rhodes Island, gia nhập Endfield theo lời tiến cử trực tiếp của Endministrator. Dưới hiệp định hợp t\xe1c giữa hai tổ chức, c\xf4 phục vụ trực tiếp dưới quyền chỉ huy của Endministrator.  Trước khi đến với Tập Đo\xe0n Endfield, Laevatain từng đơn độc rong ruổi khắp Talos-II để theo đuổi mục ti\xeau ri\xeang. Với kỹ năng chiến đấu độc lập xuất sắc, c\xf4 thường bị lầm tưởng l\xe0 \\"kẻ kh\xf3 gần\\". Thực tế lại ho\xe0n to\xe0n tr\xe1i ngược. Chỉ l\xe0 bản chất ch\xe2n th\xe0nh, thẳng thắn của c\xf4 đ\xf4i khi thể hiện qu\xe1 r\xf5, dẫn đến hiểu lầm.  Đ\xf4i l\xfac, c\xf4 n\xf3i về \\"k\xfd ức\\" một c\xe1ch b\xed ẩn, như thể cố \xfd giấu đi con người thật của m\xecnh.  C\xf4 điều khiển ngọn lửa thuần thục, nhưng lại m\xea ăn kem lạnh v\xf4 c\xf9ng. Với Laevatain, sự m\xe2u thuẫn ấy dường như l\xe0 điều tự nhi\xean.  \\n \\"Nếu vẫn thấy lạnh h\xe3y gần t\xf4i xem sao\\".","operator.content.laevatain.name":"Laevatain","operator.content.lastrite.intro":"\\"C\xf3 vẻ... t\xf4i c\xf3 li\xean quan g\xec đ\xf3 đến chiến tranh?\\"  Trước khi được người Sarkaz của th\xe0nh phố nổi t\xecm ra, Last Rite từng l\xe0 một c\xf4 g\xe1i dịu d\xe0ng được đ\xf4i vợ chồng tr\xf4ng mộ Caprinae nhận nu\xf4i. Dưới sự uốn nắn của họ, c\xf4 g\xe1i Nachzehrer trẻ tuổi kh\xf4ng c\xf2n xới tung x\xe1c chết, k\xecm n\xe9n bản năng ăn thịt. Nhưng sự kiềm chế ấy khiến c\xf4 ch\xecm trong cơn đ\xf3i khắc khoải v\xe0 sự bất an khiến c\xf4 xa l\xe1nh mọi người.  Một cuộc gặp gỡ định mệnh đ\xe3 h\xe9 lộ tiềm năng của Last Rite cho Seš\'qa. V\xec tin v\xe0o lời hứa về \\"c\xf4ng việc ngắn ng\xe0y lương cao\\" v\xe0 \\"huấn luyện để chế ngự bản năng,\\" c\xf4 được c\xe1c thương nh\xe2n quen mặt gọi l\xe0 C\xf4ng Ch\xfaa của T\xf2a \xc1n Chiến Tranh. Giờ đ\xe2y, kho\xe1c l\xean m\xecnh bộ gi\xe1p nguy\xean mẫu Witching Hour, c\xf4 điều khiển băng gi\xe1 v\xe0 th\xe9p v\xec sự nghiệp của Tập Đo\xe0n Endfield – vừa để ho\xe0n th\xe0nh hợp đồng, vừa để vươn tới tương lai h\xf2a b\xecnh m\xe0 Endfield vạch ra. \\n \\"Nếu hợp đồng của t\xf4i với Seš’qa hết hạn, ng\xe0i c\xf3 thể li\xean lạc với t\xf4i… \xd4i kh\xf4ng! T\xf4i kh\xf4ng n\xean n\xf3i ra điều đ\xf3! L\xe0m ơn... đừng n\xf3i với ai về chuyện n\xe0y nh\xe9...\\"","operator.content.lastrite.name":"Last Rite","operator.content.lifeng.intro":"\\"T\xf4i đến Endfield để học hỏi. Nhưng... c\xf3 qu\xe1 nhiều thứ cần học. T\xf4i sẽ nỗ lực hết m\xecnh\\"  Lifeng, sinh ra tại Th\xe0nh Phố V\xf5 Lăng, hiện l\xe0 thực tập sinh tại Đội Chuy\xean Vi\xean Kỹ Thuật của Tập Đo\xe0n Endfield.  Ở V\xf5 Lăng, Lifeng được y\xeau mến với danh xưng \\"Thủ Lĩnh Nh\xed\\". Qua nhiều năm, Da Pan đ\xe3 r\xe8n giũa kỹ năng thương thuật cho cậu, chuẩn bị cho h\xe0nh tr\xecnh đi t\xecm c\xf4ng l\xfd. \xcdt ai ngờ, đằng sau nụ cười rạng rỡ l\xe0 mảng tối đ\xe8 n\xe9n l\xean cậu: một tai nạn đ\xe3 ph\xe1 vỡ gia đ\xecnh hạnh ph\xfac của cậu, khiến cậu mất đi một c\xe1nh tay. Nhưng nghịch cảnh chẳng thể quật ng\xe3 cậu. Với tr\xe1i tim ch\xe2n th\xe0nh v\xe0 ngọn lửa nhiệt huyết, Lifeng kh\xf4ng ngừng vươn l\xean, kh\xe1t khao ng\xe0y c\xf3 thể g\xe1nh v\xe1c những trọng tr\xe1ch lớn lao. Một ng\xe0y n\xe0o đ\xf3, cậu sẽ đứng vững tr\xean đ\xf4i ch\xe2n m\xecnh, trở về che chở cho m\xe1i ấm đang chờ đợi.  \\n \\"Một ng\xe0y n\xe0o đ\xf3, t\xf4i sẽ đủ khả năng đảm nhận những nhiệm vụ kh\xf3 nhất. Xin h\xe3y chờ đợi ng\xe0y đ\xf3, Endmin.\\"","operator.content.lifeng.name":"Lifeng","operator.content.perlica.intro":"\\"Ch\xfang t\xf4i chiến đấu kh\xf4ng ngừng nghỉ... bởi v\xec ch\xfang t\xf4i tin ng\xe0i sẽ quay trở lại.\\"  Perlica l\xe0 Gi\xe1m S\xe1t Vi\xean của Tập Đo\xe0n Endfield, đồng thời l\xe0 người ph\xe1t ng\xf4n ch\xednh thức của tổ chức. C\xf4 chịu tr\xe1ch nhiệm ch\xednh trong việc dẫn dắt v\xe0 th\xfac đẩy sự ph\xe1t triển cũng như ứng dụng c\xf4ng nghệ Giao Thức Originium, đồng thời quản l\xfd hoạt động của Dijiang.  L\xe0 một chuy\xean gia xuất ch\xfang về Giao Thức C\xf4ng Nghệ, Perlica đ\xe3 ti\xean phong trong c\xe1c nghi\xean cứu mang t\xednh đột ph\xe1, định h\xecnh sự ph\xe1t triển v\xe0 ứng dụng linh hoạt của c\xf4ng nghệ n\xe0y, đồng thời ho\xe0n thiện Khu Phức Hợp C\xf4ng Nghiệp Tự Động (Nh\xe0 M\xe1y Khu Phức Hợp).  C\xf4 lu\xf4n b\xecnh tĩnh v\xe0 quyết đo\xe1n khi đối mặt với mọi khủng hoảng. Tuy nhi\xean, Endministrator thường phải đương đầu với những thử th\xe1ch vượt qu\xe1 mọi dự đo\xe1n. Trong thời gian Endministrator ngủ đ\xf4ng, Perlica đ\xe3 đảm nhận vai tr\xf2 chỉ huy Đội Ứng Ph\xf3 Nguy Cảnh, dẫn dắt c\xe1c anh h\xf9ng của Tập Đo\xe0n Endfield trong cuộc chiến v\xec một l\xfd tưởng vĩ đại. Kh\xf4ng ngừng nghỉ, Perlica rong ruổi khắp V\xe0nh Đai Văn Minh, l\xe0m tất cả để duy tr\xec trật tự v\xe0 vận h\xe0nh mọi thứ trơn tru.  \\n \\"Chỉ khi đặt ch\xe2n l\xean mảnh đất n\xe0y, ta mới thực sự cảm nhận được nhịp thở v\xe0 mạch sống nơi đ\xe2y... V\xe0 đ\xf3 ch\xednh l\xe0 điều m\xe0 Endfield đang đấu tranh.\\"","operator.content.perlica.name":"Perlica","operator.content.pogranichnik.intro":"\\"T\xecnh h\xecnh rất cấp b\xe1ch. T\xf4i tr\xe2n trọng đề nghị ng\xe0i t\xf3m tắt kế hoạch t\xe1c chiến của m\xecnh trong thời gian sớm nhất\\".  Pogranichnik, c\xe1n vi\xean thuộc Rhodes Island được ph\xe2n c\xf4ng đến Tập Đo\xe0n Endfield, đảm nhận vai tr\xf2 cố vấn qu\xe2n sự theo thỏa thuận hợp t\xe1c giữa hai b\xean.  Với kiến thức uy\xean th\xe2m về l\xfd thuyết qu\xe2n sự v\xe0 kinh nghiệm chiến đấu đồng đội được t\xf4i luyện qua gian kh\xf3, anh dẫn dắt đơn vị vượt qua những khủng hoảng bất ngờ nhất. Từng l\xe0 chỉ huy của Đơn Vị Khi\xean Vệ thuộc Hội Lời Thề Th\xe9p, Pogranichnik c\xf9ng c\xe1c chiến binh của m\xecnh được t\xf4n vinh l\xe0 lực lượng đ\xe1ng tin cậy nhất tr\xean chiến tuyến chống lại Aggeloi. Khi t\xecnh h\xecnh tr\xean Talos-II ng\xe0y c\xe0ng rối loạn, anh kh\xf4ng ch\xfat do dự gia nhập Tập Đo\xe0n Endfield. Với niềm tin m\xe3nh liệt, anh tin rằng Endministrator sẽ dẫn dắt Talos-II mở ra một con đường mới, đ\xfang như kh\xe1t vọng anh từng ấp ủ.  \\n \\"Endmin, t\xf4i tin chắc rằng h\xe0nh động của cậu sẽ đặt dấu chấm hết cho v\xf2ng xo\xe1y chiến tranh v\xe0 hy sinh t\xe0n khốc n\xe0y\\".","operator.content.pogranichnik.name":"Pogranichnik","operator.content.rossi.intro":"“Với người ưu t\xfa như em th\xec đơn giản!”  Rossina Wulfperl Luppino, em g\xe1i của Wulfgard, Vi\xean Ngọc Tộc S\xf3i. Trong cuộc xung đột giữa Tộc S\xf3i v\xe0 Bonekrusher, rất nhiều s\xf3i trưởng l\xe3o trong tộc đ\xe3 phải trả gi\xe1 bằng m\xe1u để cứu c\xf4 b\xe9. Ng\xe0y ấy, m\xe1u đ\xe3 nhuộm đỏ tấm khăn quấn quanh c\xf4 b\xe9…  Wulfgard hoạt động t\xe1ch biệt với tộc suốt nhiều năm, nhưng khi Tộc S\xf3i cần một người đứng đầu, Rossi đ\xe3 lựa chọn g\xe1nh lấy tr\xe1ch nhiệm ấy. C\xf4 lu\xf4n tin rằng người anh trai sớm vang danh khi c\xf2n rất trẻ mới xứng đ\xe1ng dẫn dắt to\xe0n Tộc S\xf3i. V\xec thế, Rossi kh\xf4ng ngừng nhắc nhở v\xe0 th\xfac giục anh đảm nhận vị tr\xed đ\xf3. Dẫu c\xe1c bậc trưởng l\xe3o trong tộc mong c\xf4 c\xf3 thể d\xe0nh nhiều thời gian để sống đ\xfang với đam m\xea như những c\xf4 g\xe1i c\xf9ng tuổi, Rossi vẫn kh\xf4ng thể gạt bỏ g\xe1nh nặng mang t\xean “tr\xe1ch nhiệm” trong l\xf2ng. V\xec gia đ\xecnh, v\xec tộc nh\xe2n, c\xf4 kh\xf4ng ngừng r\xe8n giũa bản th\xe2n để trở n\xean vững v\xe0ng v\xe0 mạnh mẽ hơn.  Rossi lu\xf4n mơ về những c\xe2u chuyện anh h\xf9ng, c\xf3 những khi cũng mơ mộng rằng sẽ c\xf3 một ng\xe0y c\xf4 được dấn th\xe2n v\xe0o những cuộc phi\xeau lưu c\xf9ng c\xe1c anh h\xf9ng trứ danh. Đ\xf3 ch\xednh l\xe0 khoảnh khắc “cho ri\xeang m\xecnh” hiếm hoi m\xe0 c\xf4 \xe2m thầm g\xecn giữ.  “Ch\xfang cắn r\xe1t đấy, nhưng Tộc S\xf3i kh\xf4ng sợ sẹo đ\xe2u!”","operator.content.rossi.name":"Rossi","operator.content.snowshine.intro":"\\"Gi\xf3 vừa phải. Tầm nh\xecn tốt. Thời tiết l\xfd tưởng để trượt tuyết đấy\\".  Snowshine l\xe0 c\xe1n vi\xean thuộc Rhodes Island được ph\xe2n c\xf4ng đến Tập Đo\xe0n Endfield để đảm nhiệm vai tr\xf2 chuy\xean gia t\xecm kiếm v\xe0 cứu nạn (SAR) theo hiệp định hợp t\xe1c giữa hai tổ chức.  V\xec những l\xfd do ai cũng r\xf5, c\xe1c v\xf9ng cực đ\xedch thực của Talos-II vẫn l\xe0 chốn cấm đối với nh\xe2n loại. Song, khi dự \xe1n mở rộng bi\xean cương được tiếp tục, những chuy\xean gia như Snowshine, am hiểu địa l\xfd v\xf9ng cực v\xe0 cao nguy\xean, ng\xe0y c\xe0ng được trọng dụng tại V\xe0nh Đai Văn Minh.  Do khan hiếm nh\xe2n t\xe0i, Snowshine v\xe0 đội cứu hộ của c\xf4 lu\xf4n bận rộn, kể cả trong những ng\xe0y kh\xf4ng c\xf3 nhiệm vụ đặc biệt.  D\xf9 lịch tr\xecnh d\xe0y đặc, c\xf4 vẫn d\xe0nh thời gian rảnh để viết Cẩm Nang Sinh Tồn V\xf9ng Cực, cuốn s\xe1ch giờ đ\xe2y trở th\xe0nh t\xe0i liệu chủ chốt cho c\xe1c hoạt động sinh tồn v\xe0 cứu nạn trong m\xf4i trường băng tuyết khắc nghiệt của Talos-II.  \\n \\"T\xf4i th\xedch tuyết, những ngọn n\xfai trắng phủ đầy tuyết, v\xe0 vẻ đẹp lấp l\xe1nh chỉ hiện ra trong c\xe1i lạnh cắt da cắt thịt… Đ\xe2y l\xe0 l\xfd do t\xf4i kh\xf4ng muốn họ để lại những k\xfd ức đau thương cho những người m\xe0 họ chạm tới\\".","operator.content.snowshine.name":"Snowshine","operator.content.tangtang.intro":"“Thủ Lĩnh Tối Cao đ\xe2y! Ngươi, ngươi v\xe0 cả ngươi, tất cả đều nghe theo lệnh của ta”  Tangtang, Thủ Lĩnh Tối Cao của Trại Thanh Ba. T\xednh c\xe1ch thẳng thắn, coi trọng l\xf2ng trung th\xe0nh v\xe0 h\xe0nh động theo bản năng tự do, ph\xf3ng kho\xe1ng, kh\xf4ng chịu r\xe0ng buộc theo khu\xf4n ph\xe9p. Tangtang y\xeau sự tự do, th\xedch đ\xf9a nghịch giữa l\xe0n nước, nhưng căm gh\xe9t sự phản bội. Một khi đ\xe3 thừa nhận ai l\xe0 bạn, c\xf4 b\xe9 sẽ dốc hết sức m\xecnh để gi\xfap đỡ.  Khi mới lọt l\xf2ng, Tangtang được một người kh\xf4ng r\xf5 danh t\xednh đặt v\xe0o một chiếc giỏ tre, thả tr\xf4i theo d\xf2ng s\xf4ng, để rồi dạt đến Trại Thanh Ba. Tại đ\xe2y, c\xf4 b\xe9 được D\xe2n Trại cưu mang, nu\xf4i nấng v\xe0 trở th\xe0nh một phần của Trại. Trong mắt nhiều người, Tangtang vẫn chỉ l\xe0 đứa trẻ cần được chở che, nhưng trong s\xe2u thẳm t\xe2m hồn, c\xf4 từ l\xe2u đ\xe3 hạ quyết t\xe2m g\xe1nh v\xe1c tương lai của Trại Thanh Ba.  Tuy trải qua kh\xf4ng \xedt biến cố nhưng ngọn lửa nhiệt huyết trong c\xf4 b\xe9 chưa từng lụi t\xe0n. Để giải đ\xe1p cho những ho\xe0i nghi trong l\xf2ng v\xe0 đưa Trại Thanh Ba ph\xe1t triển hơn nữa, Tangtang đ\xe3 gia nhập Tập Đo\xe0n Endfield.  “Đừng để c\xf4 b\xe9 thấy Mi Fu, nếu kh\xf4ng th\xec rối tung hết l\xean đấy.” — theo lời c\xe1n vi\xean ở Văn Ph\xf2ng Trưởng Vận Chuyển.  “Gọi ta đến chỉ để khen th\xf4i \xe0? Thế th\xec khen nhiều v\xe0o. Ta th\xedch nghe lời n\xf3i thật lắm!”","operator.content.tangtang.name":"Tangtang","operator.content.wulfgard.intro":"\\"T\xf4i biết sức mạnh kh\xf4ng phải l\xe0 tất cả, nhưng ở đất Talos-II m\xe0 kh\xf4ng c\xf3 sức mạnh th\xec kh\xf3 sống.\\"  Catello Wulfgard Luppino, l\xednh đ\xe1nh thu\xea trẻ tuổi sống ở r\xeca V\xe0nh Đai Văn Minh, hiện l\xe0m việc cho Đội Ứng Ph\xf3 Nguy Cảnh tại Tập Đo\xe0n Endfield. D\xf9 c\xf2n trẻ, Wulfgard đ\xe3 hiểu r\xf5 bản chất dễ thay l\xf2ng đổi dạ của con người. Nhưng những chuyện ấy kh\xf4ng l\xe0m cậu gục ng\xe3, tr\xe1i lại c\xe0ng khiến cậu ch\xedn chắn vượt trội hẳn so với độ tuổi. Cậu kh\xf4ng chủ động g\xe2y sự m\xe0 khi thấy c\xf3 biến, cậu chọn tr\xe1nh đối đầu trực diện. Với t\xe0i năng trong t\xe1c chiến t\xe0ng h\xecnh v\xe0 trinh s\xe1t, Wulfgard c\xf3 thể đi s\xe1t b\xean kẻ th\xf9, chờ thời cơ tung đ\xf2n ch\xed tử khi ch\xfang \xedt ngờ tới nhất.  L\xe0 th\xe0nh vi\xean của tộc Landbreaker, biệt danh Băng Nh\xf3m Pack, Wulfgard l\xe0 đồng minh đ\xe1ng tin cậy nếu bạn chinh phục được l\xf2ng tin của cậu ta. Nhưng đ\xf3 l\xe0 thử th\xe1ch kh\xf4ng hề đơn giản.  \\n \\"Chủ nghĩa l\xfd tưởng phi thực tế ph\xe1 hủy nhiều cuộc đời hơn l\xe0 cứu rỗi.\\"","operator.content.wulfgard.name":"Wulfgard","operator.content.xaihi.intro":"\\"Một khi ta đo\xe0n kết, cơ mưu sẽ sinh khởi.\\"  Xaihi, xuất th\xe2n từ Tu Hội Tĩnh Lặng l\xe0 tổ chức nghi\xean cứu được Lateran ph\xe1i đến Talos-II để kh\xe1m ph\xe1 c\xf4ng nghệ. L\xe0 người theo chủ nghĩa Hội Luận, c\xf4 tin rằng t\xednh to\xe1n v\xe0 ph\xe2n t\xedch ng\xf4n ngữ sẽ dẫn lối đến Ch\xe2n L\xfd.  C\xf4 giao tiếp với m\xe1y m\xf3c thuần thục hơn l\xe0 với con người. T\xe0i năng xuất ch\xfang trong c\xf4ng nghệ th\xf4ng tin của c\xf4 được ch\xednh Nữ Viện Trưởng của Đại Tu Viện trong Tu Hội Tĩnh Lặng c\xf4ng nhận. D\xf9 việc n\xe2ng cấp \\"tr\xe1i ph\xe9p\\" m\xe1i v\xf2m của Gi\xe1o Đường từng g\xe2y ra h\xe0ng loạt sự cố, Nữ Viện Trưởng vẫn hết l\xf2ng tiến cử c\xf4 đến Tập Đo\xe0n Endfield, hy vọng c\xf4 t\xecm được nơi xứng tầm để thể hiện t\xe0i năng.  Giờ đ\xe2y, Xaihi l\xe0m việc tr\xean t\xe0u Dijiang, đảm nhiệm c\xe1c nhiệm vụ kỹ thuật th\xf4ng tin như x\xe2y dựng Mạng Lưới Protorig v\xe0 t\xedch hợp hệ thống. Những hiểu biết độc đ\xe1o về Mạng Lưới Originium, kết hợp với tri thức s\xe2u sắc từ Tu Hội, khiến c\xf4 trở th\xe0nh một th\xe0nh vi\xean kh\xf4ng thể thiếu của Endfield.  \\n \\"\xd4i Tri Thức cổ xưa nhất, xin đừng dẫn ch\xfang t\xf4i v\xe0o c\xe1m dỗ m\xe0 h\xe3y giải tho\xe1t ch\xfang t\xf4i khỏi m\xe3 độc hại… Thưa Endministrator, t\xf4i l\xe0 Xaihi. Xin h\xe3y soi s\xe1ng cho t\xf4i.\\"","operator.content.xaihi.name":"Xaihi","operator.content.yvonne.intro":"\\"Cặp s\xfang lục n\xe0y vừa tay lắm! Hừm... T\xf4i vừa ph\xe1t hiện v\xe0i điểm c\xf3 thể cải tiến thiết kế. Th\xf4i th\xec chỉnh lại th\xe0nh phi\xean bản đặc biệt của Yvonne vậy!\\"  Yvonne, c\xe1n vi\xean thuộc Đội Chuy\xean Vi\xean Kỹ Thuật của Tập Đo\xe0n Endfield, hiện phụ tr\xe1ch nghi\xean cứu về \xc6ther, Nhiễm Khuẩn v\xe0 c\xe1c thiết bị li\xean quan.  Thoạt nh\xecn, Yvonne tựa như một t\xedn đồ thời trang nổi loạn với sừng, đu\xf4i v\xe0 m\xf3ng tay rực rỡ sắc m\xe0u. C\xf4 sẵn s\xe0ng bỏ qua c\xe1c hội nghị học thuật để săn l\xf9ng tạp ch\xed thời trang mới nhất hay album nhạc thịnh h\xe0nh. Lu\xf4n bị cuốn h\xfat bởi những g\xec mới mẻ v\xe0 kh\xe1c biệt, Yvonne c\xf3 biệt t\xe0i dẫn đầu xu hướng, bước đi theo nhịp điệu ri\xeang.  Nhưng chẳng ai phủ nhận c\xf4 l\xe0 một thi\xean t\xe0i. Ngay từ thời học đường, c\xf4 đ\xe3 gom về v\xf4 số giải thưởng nghi\xean cứu khoa học m\xe0 người kh\xe1c chỉ d\xe1m mơ. Ai cũng nghĩ c\xf4 sẽ gia nhập một học viện đỉnh cao, dẫn dắt lĩnh vực của m\xecnh. Thế nhưng, Yvonne quay lưng với tất cả để chọn gia nhập Endfield.  L\xfd do ư? C\xf4 chưa từng h\xe9 lộ. Nếu muốn biết, c\xf3 lẽ ng\xe0i n\xean tự hỏi c\xf4 ấy.  \\n \\"T\xf4i c\xf3 thể sơn lại trang bị của m\xecnh kh\xf4ng? M\xe0u hiện tại kh\xf4ng hợp với t\xf3c t\xf4i lắm\\".","operator.content.yvonne.name":"Yvonne","operator.detail.back":"Trở lại Danh S\xe1ch C\xe1n Vi\xean","operator.elem.electric":"Điện","operator.elem.fire":"Nhiệt","operator.elem.ice":"Băng","operator.elem.nature":"Tự Nhi\xean","operator.elem.physic":"Vật L\xfd","operator.filter.all":"Tất cả","operator.filter.elem":"Nguy\xean tố","operator.filter.prof":"Lớp","operator.more":"Tất Cả C\xe1n Vi\xean","operator.prof.assault":"Đấu Sĩ","operator.prof.caster":"Ph\xe1p Sư","operator.prof.guard":"Vệ Binh","operator.prof.shielder":"Hộ Vệ","operator.prof.support":"Trợ Thủ","operator.prof.vanguard":"Ti\xean Phong","operator.race":"Chủng Tộc","operator.races.0":"Kh\xf4ng Tiết Lộ","operator.races.1":"Anasa","operator.races.10":"Caprinae","operator.races.11":"Cautus","operator.races.12":"Savra","operator.races.13":"Sankta","operator.races.14":"Sarkaz","operator.races.15":"Vouivre","operator.races.16":"Vulpo","operator.races.17":"Ursus","operator.races.18":"Kylin","operator.races.2":"Anaty","operator.races.3":"Phidia","operator.races.4":"Feline","operator.races.5":"Kuranta","operator.races.6":"Liberi","operator.races.7":"Long","operator.races.8":"Lupo","operator.races.9":"Perro","reserveFooter.title":"Đăng k\xfd trước","reserveFooter.titleReserved":"Ho\xe0n tất đăng k\xfd trước","reserveFooter.titleReserved2":"Ch\xe0o mừng đến với Talos-II","section.aic":"Th\xf4ng Tin Nh\xe0 M\xe1y Khu Phức Hợp","section.gameplay":"Lối Chơi","section.information":"Truyền Th\xf4ng","section.lore":"Truyền Sử","section.milestone":"C\xe1c Mốc Đăng K\xfd Trước To\xe0n Cầu Của Endfield","section.notice":"Tin Tức","subpage.news.empty":"Chưa c\xf3 nội dung","subpage.news.title":"Tin Tức","subpage.video.empty":"Chưa c\xf3 nội dung","subpage.video.title":"Video","toast.networkError":"Lỗi mạng","operator.content.zhuangfy.name":"Zhuang Fangyi","operator.content.zhuangfy.intro":"\\"Chỉ cần kh\xf4ng bỏ cuộc l\xe0 sẽ kh\xf4ng bao giờ thất bại\\". \\nC\xe1n Vi\xean Zhuang Fangyi, hiện giữ chức Ph\xf3 Vương của Quận Ph\xe1t Triển Khoa Học V\xf5 Lăng, đồng thời l\xe0 Thi\xean Sư phụ tr\xe1ch Dự \xc1n Vật Liệu Mới Gốc Xiranite. Theo đề cử của Học Viện Khoa Học Hongshan, c\xf4 đ\xe3 hợp t\xe1c với Tập Đo\xe0n Endfield để tiến h\xe0nh nghi\xean cứu li\xean quan đến c\xe1c khe nứt kh\xf4ng gian. \\nXuất th\xe2n từ Hongshan, Zhuang Fangyi bộc lộ thi\xean ph\xfa phi thường ngay từ khi c\xf2n nhỏ v\xe0 sớm được tuyển thẳng v\xe0o Hệ Thống Học Viện trực thuộc Cục Thi\xean Sư nhờ th\xe0nh t\xedch học tập xuất sắc. Sau đ\xf3, với năng lực vượt trội, c\xf4 được chọn tham gia Dự \xc1n Xiranite, trở th\xe0nh th\xe0nh vi\xean trẻ tuổi nhất của Trạm Khoa Học V\xf5 Lăng. Sau thảm họa khiến gần như to\xe0n bộ nh\xe2n vi\xean tại Trạm Khoa Học thiệt mạng, c\xf4 được bổ nhiệm l\xe0m Ph\xf3 Vương d\xf9 l\xe0 người trẻ nhất, g\xe1nh tr\xean vai trọng tr\xe1ch dẫn dắt v\xe0 ph\xe1t triển tr\xean to\xe0n V\xf5 Lăng. \\nĐược bổ nhiệm trong thời khắc khủng hoảng, c\xf4 nhanh ch\xf3ng vực lại tinh thần. Chỉ sau một thập kỷ, c\xf4 kh\xf4ng chỉ x\xe2y dựng V\xf5 Lăng th\xe0nh đ\xf4 thị phồn thịnh, m\xe0 c\xf2n từng bước vượt qua v\xf4 v\xe0n thử th\xe1ch để trở th\xe0nh người l\xe3nh đạo tận tụy v\xe0 c\xf3 tr\xe1ch nhiệm. Dẫu vậy, thảm họa xảy ra mười năm trước vẫn nhức nhối trong tr\xe1i tim tất cả mọi người, khiến c\xf4 kh\xf4ng ng\xe0y n\xe0o qu\xean rằng sự b\xecnh y\xean v\xe0 thịnh vượng của Th\xe0nh Phố V\xf5 Lăng c\xf3 thể tan biến chỉ trong chớp mắt. \\n\\"C\xf2n người l\xe0 c\xf2n của\\".","operator.content.camille.name":"Camille","operator.content.camille.intro":"\\"Từ nơi tận c\xf9ng b\xf3ng tối, lại th\xeam một giọt m\xe1u phải trả.\\" \\nCamille Arno, một Hộ Thần đến từ Seš\'qa, chuy\xean phụ tr\xe1ch xử l\xfd c\xe1c vụ việc bạo lực c\xf3 li\xean quan đến Sarkaz hoặc nhắm v\xe0o Sarkaz. L\xe0 một trong những Hộ Thần tinh nhuệ nhất, anh đ\xe3 lĩnh hội Thuật Ph\xe1p Originium li\xean quan đến huyết dịch, đồng thời đặc biệt thiện nghệ trong việc đối ph\xf3 với đủ loại vu thuật hiểm \xe1c. \\nV\xec Seš\'qa, qu\xea hương của m\xecnh, Camille đ\xe3 đ\xedch th\xe2n truy bắt v\xf4 số tội phạm nguy hiểm. Thế nhưng, trong cuộc truy l\xf9ng người th\xe2n c\xf9ng huyết thống của m\xecnh, anh lại li\xean tiếp vấp phải trở ngại. Bị khắc s\xe2u bởi những phản bội trong qu\xe1 khứ, anh đ\xe3 quen với việc giữ cho m\xecnh vẻ lạnh l\xf9ng, xa c\xe1ch, đồng thời lảng tr\xe1nh sự quan t\xe2m từ người kh\xe1c - đ\xf3 l\xe0 c\xe1ch anh tự bảo vệ bản th\xe2n. Tuy vậy, trước những người bạn đ\xe3 gi\xe0nh được l\xf2ng tin của anh, Camille vẫn sẵn l\xf2ng bộc lộ một mặt ch\xe2n th\xe0nh v\xe0 thẳng thắn. \\nHiện tại, anh đang t\xecm kiếm cơ hội hợp t\xe1c với Tập Đo\xe0n Endfield tr\xean danh nghĩa c\xe1 nh\xe2n. Anh mong được c\xf9ng bạn l\xean đường tới những miền đất xa x\xf4i, để ho\xe0n th\xe0nh những t\xe2m nguyện đ\xe3 được ấp ủ từ rất l\xe2u trong l\xf2ng cả hai. \\n\\"N\xe0y bạn t\xf4i, mấy c\xe1i danh hiệu v\xf4 nghĩa chẳng đ\xe1ng bận t\xe2m nữa. D\xf2ng m\xe1u của t\xf4i sẽ m\xe3i b\xean bạn.\\"","operator.content.mifu.name":"Mi Fu","operator.content.mifu.intro":"\\"Ch\xfang ta l\xe0 đồng đội từng v\xe0o sinh ra tử c\xf9ng nhau, đ\xfang chứ?\\" \\nMi Fu, Đội Trưởng Đội Cảnh Vệ V\xf5 Lăng, c\xe1nh tay phải được Ph\xf3 Vương Thi\xean Sư Zhuang Fangyi. L\xe0 gương mặt quen thuộc của danh hiệu \\"Ng\xf4i Sao Ti\xean Phong\\" nhiều năm liền tại V\xf5 Lăng, c\xf4 hiện đứng thứ hai tr\xean bảng xếp hạng năng lực chiến đấu d\xe2n sự của th\xe0nh phố. Trong mắt đồng li\xeau, c\xf4 vừa l\xe0 người huấn luyện nghi\xeam khắc nhất, cũng l\xe0 cấp tr\xean biết quan t\xe2m nhất. L\xe0 kh\xe1ch quen của quầy b\xe1nh gạo ngọt tr\xean Đại Lộ Phương Hưng, l\xe0 anh h\xf9ng trong mắt trẻ nhỏ, l\xe0 cơn \xe1c mộng của đ\xe1m g\xe2y rối, v\xe0 l\xe0 mối đại họa đối với bất kỳ kẻ x\xe2m nhập n\xe0o. D\xf9 bị Trại Thanh Ba g\xe1n cho danh xưng \\"kẻ phản bội\\", c\xf4 vẫn l\xe0 người thừa kế ch\xe2n ch\xednh của V\xf5 Học Thanh Ba. L\xe0 bạn thuở nhỏ, đồng thời cũng l\xe0 đối thủ của Tangtang, c\xf4 đ\xe3 chiến đấu đến c\xf9ng trước Triều Nhiễm Khuẩn m\xe0 chưa từng l\xf9i bước... \\nNếu muốn hiểu Mi Fu r\xf5 hơn, bạn chỉ c\xf3 thể trở th\xe0nh đối thủ của c\xf4, hoặc trở th\xe0nh bạn của c\xf4 - đ\xf3 l\xe0 hai mối quan hệ duy nhất c\xf4 thật sự coi trọng. Một b\xean khiến m\xe1u trong người c\xf4 s\xf4i l\xean; b\xean c\xf2n lại khiến c\xf4 sẵn s\xe0ng tung ra từng c\xfa đấm m\xe0 kh\xf4ng m\xe0ng sống chết. \\nGiờ đ\xe2y, để đ\xe1p lại những người bạn đ\xe3 từng chiến đấu b\xean m\xecnh, đồng thời t\xecm kiếm th\xeam những đối thủ xứng đ\xe1ng để giao phong hết lần n\xe0y đến lần kh\xe1c, c\xf4 đ\xe3 bắt đầu h\xe0nh tr\xecnh trao đổi tại Tập Đo\xe0n Endfield. \\n\\"Lần n\xe0y t\xf4i sẽ dọn dẹp hộ đống rối rắm n\xe0y.\\"","home.title.v1d3":"Ph\xe1c Họa\\nGia Bảo Thất Lạc","header.goToGame":"Đến Tr\xf2 Chơi","operator.content.lizhiyan.name":"Arcane","operator.content.lizhiyan.intro":"\\"T\xf4i sẽ bảo vệ danh dự của Đội Đặc Nhiệm.\\" \\nL\xe0 đội trưởng của Đội Đặc Nhiệm Yinglung (ĐĐNY), Arcane đ\xe3 đồn tr\xfa tại Đ\xe8o Yinglung được một thời gian d\xe0i, từng nhiều lần thực hiện c\xe1c nhiệm vụ khảo s\xe1t b\xean trong khu cấm. C\xf4 l\xe0 một người nghi\xeam t\xfac, tỉ mỉ v\xe0 hiếm khi nở nụ cười. \\nThảm họa tại Khu Cấm Bắc V\xf5 Lăng đ\xe3 cướp đi của Arcane tất cả mọi thứ. Kể từ đ\xf3, mục đ\xedch sống duy nhất của c\xf4 l\xe0 kiềm tỏa Khe Nứt Cực Lớn V\xf5 Lăng. C\xf4 từng kh\xf4ng \xedt lần dấn th\xe2n v\xe0o s\xe2u trong hiểm cảnh. Hận th\xf9 dẫn dắt từng bước ch\xe2n c\xf4 v\xe0o Vực S\xe2u, nhưng ch\xednh n\xf3 cũng l\xe0 thứ giữ cho c\xf4 sống s\xf3t khi mọi hy vọng dường như đ\xe3 ti\xeau tan. \\nỞ Arcane hội tụ đủ mọi phẩm chất của một th\xe0nh vi\xean ĐĐNY: tuyệt đối chấp h\xe0nh mệnh lệnh, chỉ huy chiến thuật xuất ch\xfang, r\xe8n luyện kh\xf4ng ngừng nghỉ ng\xe0y đ\xeam v\xe0 một tinh thần bất khuất. Những ai từng mất đi người th\xe2n trong thảm họa đều c\xf3 thể thấy một phần h\xecnh b\xf3ng của ch\xednh m\xecnh trong Arcane... \\nMột số người thấy c\xf4 thật lạnh l\xf9ng, nhưng đối với c\xe1c th\xe0nh vi\xean ĐĐNY, việc giữ khoảng c\xe1ch cũng l\xe0 một c\xe1ch để bảo vệ cho nhau. \\n\\"\xdd ch\xed sắt đ\xe1, h\xe0nh động dứt kho\xe1t. Yinglung lấy thế m\xe0 thắng.\\"","operator.content.liino.name":"Liino","operator.content.liino.intro":"\\"Lấp la lấp l\xe1nh! M\xe0n tr\xecnh diễn mới nhất sắp bắt đầu đ\xe2y!\\" \\nLiino l\xe0 một thần tượng thế hệ mới v\xf4 c\xf9ng nổi bật, xuất th\xe2n từ Ph\xf2ng Thương Mại Tổng Hợp Talos-II. Được c\xf4ng ch\xfang y\xeau mến ngay từ khi mới ra mắt, c\xf4 được mệnh danh l\xe0 \\"Sao Mai của La Fantoma\\". Nổi tiếng nhờ giọng h\xe1t tinh tế c\xf9ng phong c\xe1ch biểu diễn độc đ\xe1o, c\xe1c concert của c\xf4 thường ph\xe1 vỡ mọi quy chuẩn v\xe0 th\xe1ch thức những th\xf4ng lệ của ng\xe0nh giải tr\xed. \\nC\xf4 lu\xf4n mang đến trải nghiệm c\xf3 một kh\xf4ng hai cho kh\xe1n giả, khiến c\xe1c tập đo\xe0n lớn l\xfac n\xe0o cũng phải tranh nhau xếp h\xe0ng để t\xe0i trợ cho mỗi buổi diễn của c\xf4. D\xf9 sự nghiệp đi l\xean như diều gặp gi\xf3 của c\xf4 n\xe0ng Sarkaz Djall n\xe0y kh\xf4ng thiếu những tranh c\xe3i, nhưng bất kỳ ai khi đ\xe3 chứng kiến c\xf4 tr\xean s\xe2n khấu đều sẽ m\xea đắm \xe1nh h\xe0o quang rực rỡ ấy. \\nHiện tại, Liino đang từng bước x\xfac tiến c\xe1c kế hoạch cho chuyến lưu diễn quanh Talos-II. C\xf4 tin m\xecnh sẽ mang đến một m\xe0n biểu diễn tuyệt diệu chưa từng thấy, v\xe0 ng\xe0y m\xe0 c\xf4 tỏa s\xe1ng rực rỡ tr\xean đỉnh thế giới chắc chắn sẽ đến. \\n\\"\xd4i, ngọt ng\xe0o qu\xe1! T\xf4i n\xean cảm ơn thế n\xe0o mới phải đ\xe2y... Nghĩ ra rồi! T\xf4i sẽ tặng v\xe9 buổi diễn cho bạn tới khi n\xe0o huề th\xec th\xf4i, được kh\xf4ng?\\"","operator.content.typhoea.name":"Typhoeus","operator.content.typhoea.intro":"\\"Một c\xe2u chuyện hay cũng giống như một thợ săn giỏi. Cả hai đều nhắm thẳng v\xe0o tr\xe1i tim.\\" \\nTyphoeus, nữ thợ săn miền hoang d\xe3 đến từ Rhodes Island, lu\xf4n t\xf2 m\xf2 về thế giới. C\xf4 khao kh\xe1t đặt ch\xe2n đến những miền đất kh\xf4ng b\xf3ng người, chưa từng được kh\xe1m ph\xe1, để lần theo dấu vết của một qu\xe1 khứ đ\xe3 bị l\xe3ng qu\xean. \\nTr\xean Talos-II, nhiều truyền thuyết về Sami đ\xe3 phai nhạt, chỉ c\xf2n số \xedt người Samifjod vẫn ghi nhớ ch\xfang. Typhoeus quyết định lần lượt t\xecm đến từng người, ghi lại những mảnh k\xfd ức đ\xe3 vỡ vụn ấy trong cuốn sổ của m\xecnh. \\nSau khi đặt ch\xe2n đến Endfield, những c\xe2u chuyện m\xe0 c\xf4 theo đuổi kh\xf4ng c\xf2n chỉ l\xe0 những truyền thuyết đ\xe3 bị l\xe3ng qu\xean. C\xf4 gặp gỡ nhiều người bạn mới v\xe0 sẻ chia những c\xe2u chuyện với mọi người từ khắp mọi miền. \\nV\xe0 tr\xean h\xe0nh tr\xecnh truy t\xecm những truyền thuyết đ\xf3, c\xf4 cũng đang tự tay viết n\xean c\xe2u chuyện của ch\xednh m\xecnh. \\nĐến một ng\xe0y, khi từng trang trong cuốn sổ tay đều đ\xe3 được lấp đầy, c\xf4 sẽ mỉm cười n\xf3i với những người bạn b\xean cạnh: \\n\\"Truyền thuyết kh\xf4ng phải l\xfac n\xe0o cũng xa vời... Đ\xf4i khi, ch\xfang xảy ra ngay b\xean cạnh ch\xfang ta.\\"","operator.content.purrche.name":"Purrchena","operator.content.purrche.intro":"\\"Đến lượt t\xf4i... \'Meo-ch\xe0o!\'... Ư... Sao t\xf4i lại ngủ qu\xean nữa rồi?!\\" \\nPurrchena l\xe0 một t\xedn đồ cuồng nhiệt của b\xe1nh ngọt, đồng thời giữ vai tr\xf2 ph\xe1t ng\xf4n vi\xean cho Quỹ Cứu Trợ Hội Chứng Ảnh Hưởng M\xf4i Trường \xc6therside. Theo đề cử của Ph\xf2ng Thương Mại Tổng Hợp Talos-II, c\xf4 đ\xe3 gia nhập Ph\xf2ng Kinh Doanh trực thuộc Tập Đo\xe0n Endfield v\xe0 từ đ\xf3 trở th\xe0nh người li\xean lạc giữa Endfield v\xe0 Ph\xf2ng Thương Mại Tổng Hợp trong lĩnh vực li\xean quan đến Hội Chứng \xc6therside. \\nNgay từ lần đầu Purrchena xuất hiện trước c\xf4ng ch\xfang, t\xecnh y\xeau thương v\xe0 sự quan t\xe2m mọi người d\xe0nh cho c\xf4 đ\xe3 khiến Purrchena nhận ra tr\xe1ch nhiệm m\xe0 m\xecnh đang g\xe1nh v\xe1c. Thế nhưng, sau khi trở th\xe0nh gương mặt đại diện của Quỹ v\xe0 đồng h\xe0nh c\xf9ng những người mắc Hội Chứng \xc6therside, c\xf4 mới nhận ra những g\xec bản th\xe2n c\xf3 thể l\xe0m vẫn c\xf2n qu\xe1 \xedt. D\xf9 Hội Chứng \xc6therside thường khiến c\xf4 bất chợt ch\xecm v\xe0o giấc ngủ, nhưng mỗi lần thức dậy, c\xf4 lại tiếp tục l\xean đường, mang theo t\xecnh cảm mọi người d\xe0nh cho c\xf4. Theo c\xe1ch của ri\xeang m\xecnh, Purrchena lu\xf4n mang nụ cười đến với những bệnh nh\xe2n kh\xe1c m\xe0 c\xf4 đang gi\xfap đỡ. \\n\\"Kẹo marshmallow v\xe0 vi c\xe1 kh\xf4 ngoại nhập đều c\xf3 đủ rồi... Ổn, sẵn s\xe0ng l\xean đường!\\"","operator.content.endministrator2.cv.en-us":"Hyoie O\'Grady","operator.content.endministrator1.cv.en-us":"Chloe Eves","operator.content.perlica.cv.en-us":"Jane Jackson","operator.content.chen.cv.en-us":"Rebecca Hanssen","operator.content.wulfgard.cv.en-us":"Jacopo Calatroni","operator.content.arclight.cv.en-us":"Andrea Gatchalian","operator.content.ember.cv.en-us":"Rhiannon Moushall","operator.content.xaihi.cv.en-us":"Elsie Lovelock","operator.content.avywenna.cv.en-us":"Sheena May","operator.content.gilberta.cv.en-us":"Anna Devlin","operator.content.snowshine.cv.en-us":"Stephanie Southerland","operator.content.lifeng.cv.en-us":"Yung-I Chang","operator.content.laevatain.cv.en-us":"Kira Buckland","operator.content.yvonne.cv.en-us":"Clare Louise Connolly","operator.content.dapan.cv.en-us":"Jon Xu","operator.content.ardelia.cv.en-us":"Lindsay Sheppard","operator.content.akekuri.cv.en-us":"Shu Uchida","operator.content.catcher.cv.en-us":"Kevin Andrew Rivera","operator.content.estella.cv.en-us":"Risa Mei","operator.content.fluorite.cv.en-us":"Katiana Sarkissian","operator.content.antal.cv.en-us":"Jacob Craner","operator.content.alesh.cv.en-us":"Heitor Assali","operator.content.lastrite.cv.en-us":"Amber Hood","operator.content.pogranichnik.cv.en-us":"Sergey Ponomaryov","operator.content.tangtang.cv.en-us":"Jing Chen","operator.content.rossi.cv.en-us":"Giada Sabellico","operator.content.zhuangfy.cv.en-us":"Molly Zhang","operator.content.mifu.cv.en-us":"Rao Zijun","operator.content.camille.cv.en-us":"Aleks Le","operator.content.lizhiyan.cv.en-us":"Julia Gu","operator.content.liino.cv.en-us":"Maddie Matsumoto","operator.content.typhoea.cv.en-us":"Hanna Johansson","operator.content.purrche.cv.en-us":"Christine Marie Cabanos"}'),g={src:"https://web-static.hg-cdn.com/endfield/official-v4/_next/static/media/vi-vn.b39623bb.png"},A={lang:"vi-vn",text:p,font:h,langs:i.YZ,components:{footer:t.A,SvgLogo:s.A},data:{share:[{key:"twitter",url:"https://twitter.com/AKEndfield",icon:c.A},{key:"tiktok",url:"https://www.tiktok.com/@akendfielden",icon:d.A},{key:"facebook",url:"https://www.facebook.com/AKEndfieldVI/",icon:o.A},{key:"youtube",url:"https://www.youtube.com/channel/UCowPaVRBzg8CE6K4CB6LJfw",icon:u.A},{key:"discord",url:"https://discord.gg/akendfield",icon:r.A},{key:"skport",url:"https://skport.com?hg_media=endfield_official",icon:l.A}],shop:[{key:"appStore",url:"https://apps.apple.com/vn/app/arknights-endfield-vn/id6752563987"},{key:"googlePlay",url:"https://play.google.com/store/apps/details?id=com.gryphline.endfield.gp.vn"},{key:"ps5",url:""},{key:"gpg",url:""}],operator:m},images:{"bulletin.news":g.src,"bulletin.events":g.src,"bulletin.notices":g.src,"shop.reg.appStore":"https://web-static.hg-cdn.com/endfield/official-v4/_next/static/media/appStore.cdbe8382.png","shop.reg.googlePlay":"https://web-static.hg-cdn.com/endfield/official-v4/_next/static/media/google.777471a7.png","shop.get.appStore":"https://web-static.hg-cdn.com/endfield/official-v4/_next/static/media/appStore.76965f84.png","shop.get.googlePlay":"https://web-static.hg-cdn.com/endfield/official-v4/_next/static/media/googlePlay.3884c2b2.png","home.v1d4Cele":n(13344).A.src,"home.pageTitle":n(32732).A.src,"calendar.title":n(54232).A.src,"calendar.timeline":n(63395).A.src,"calendar.content":n(9265).A.src}}};
